/**
 * @fileoverview 舱室应用分发器（Cabin Dispatcher）
 *
 * 职责：
 * 1. 统一声明五舱应用的懒加载入口，避免 PortalShell 直接耦合具体文件路径。
 * 2. 提供 `preloadCabinApps` 预加载能力，在浏览器空闲时提前加载相邻舱室 chunk，
 *    降低舱室切换时的白屏等待。
 * 3. 保留 `MCPServerDashboardPage` 特殊分发（总控舱的 MCP 管理页面）。
 *
 * @module apps/cabinDispatcher
  * @doc []
*/

import React from 'react'
import type { CabinType } from '@/store/workflowStore'
import { getLogger } from '@/lib/logger'

const logger = getLogger()

const InputApp = React.lazy(() => import('@/apps/input'))
const AnalysisApp = React.lazy(() => import('@/apps/analysis'))
const TradingApp = React.lazy(() => import('@/apps/trading'))
const OutputApp = React.lazy(() => import('@/apps/output'))
const CommandApp = React.lazy(() => import('@/apps/command'))
const AgentApp = React.lazy(() => import('@/apps/command/AgentApp'))
const MCPServerDashboardPage = React.lazy(() => import('@/pages/command/MCPServerDashboardPage'))

/** 五舱应用懒加载映射 */
export const CABIN_APPS: Record<CabinType, React.LazyExoticComponent<React.ComponentType<unknown>>> = {
  input: InputApp,
  analysis: AnalysisApp,
  trading: TradingApp,
  output: OutputApp,
  command: CommandApp,
}

/** 各舱室相邻舱室（用于预加载） */
const CABIN_ADJACENCY: Record<CabinType, CabinType[]> = {
  input: ['analysis'],
  analysis: ['input', 'trading'],
  trading: ['analysis', 'output'],
  output: ['trading', 'command'],
  command: ['output'],
}

/** 预加载任务去重集合 */
const preloadedCabins = new Set<CabinType>()

/**
 * 根据当前舱室获取应渲染的应用组件。
 *
 * @param activeCabin 当前激活舱室
 * @param isAgentPath 是否处于 /command/agents 路径
 * @param isMCPPath 是否处于 /command/mcp-servers 路径
 */
export function getActiveApp(
  activeCabin: CabinType,
  isAgentPath: boolean,
  isMCPPath: boolean,
): React.LazyExoticComponent<React.ComponentType<unknown>> {
  if (activeCabin === 'command' && isAgentPath) {
    return AgentApp
  }
  if (activeCabin === 'command' && isMCPPath) {
    return MCPServerDashboardPage
  }
  return CABIN_APPS[activeCabin]
}

const PRELOADERS: Record<CabinType, () => Promise<unknown>> = {
  input: () => import('@/apps/input'),
  analysis: () => import('@/apps/analysis'),
  trading: () => import('@/apps/trading'),
  output: () => import('@/apps/output'),
  command: () => import('@/apps/command'),
}

/**
 * 预加载相邻舱室应用 chunk。
 *
 * 使用 requestIdleCallback（或 setTimeout 兜底）在浏览器空闲时触发，
 * 避免阻塞首屏渲染。已预加载的舱室会被去重。
 */
export function preloadCabinApps(activeCabin: CabinType): void {
  const adjacent = CABIN_ADJACENCY[activeCabin]
  if (!adjacent || adjacent.length === 0) return

  const schedule = typeof window !== 'undefined' && 'requestIdleCallback' in window
    ? window.requestIdleCallback
    : (cb: () => void) => setTimeout(cb, 200)

  schedule(() => {
    for (const cabin of adjacent) {
      if (preloadedCabins.has(cabin)) continue
      preloadedCabins.add(cabin)
      PRELOADERS[cabin]()
        .then(() => {
          logger.info('[cabinDispatcher] 预加载完成', { cabin })
        })
        .catch((err) => {
          logger.warn('[cabinDispatcher] 预加载失败', { cabin, error: err })
        })
    }
  })
}

/**
 * 重置预加载状态（主要用于测试）
 */
export function resetPreloadedCabins(): void {
  preloadedCabins.clear()
}

/**
 * @module DataTestPanel
 * @description 数据采集测试面板（v3）。
 *
 * 支持服务健康检查、单接口/批量链路测试，并实时展示：
 * - 采集链路时间线
 * - 实时日志流
 * - 质量指标统计
 *
 * @dataflow
 * - 执行者：本面板通过 dataTestStore.checkHealth / runSingleTrace / runBatchTrace 触发采集
 * - 数据来源：useCollectionRuntimeStore（traceSpans / logs / stats）
 * - 展示职责：
 *   - 服务健康状态 Badge（store.health）
 *   - 质量指标 StatCard × 4（runtime.stats）
 *   - 单链路测试结果（store.singleResult）
 *   - 批量采集任务表格（store.tasks）
 *   - 链路时间线 CollectionTimeline（runtime.traceSpans）
 *   - 实时日志 LiveLogStream（runtime.logs）
 */

import { useMemo } from 'react'
import { Button } from '@/components/atoms/Button'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/atoms/Card'
import { Input } from '@/components/atoms/Input'
import { Badge } from '@/components/atoms/Badge'
import { Select, SelectItem } from '@/components/atoms/Select'
import { Skeleton } from '@/components/molecules/states/Skeleton'
import { useDataTestStore, type TraceDimension } from '@/store/dataTestStore'
import { useSevenDimConfigStore } from '@/store/sevenDimConfigStore'
import { useCollectionRuntimeStore } from '@/store/collectionRuntimeStore'
import { DEFAULT_DIMENSIONS } from '@/config/collectConfig'
import { getLogger } from '@/lib/logger'
import { COLOR_TOKENS } from '@/constants/theme.tokens'
import CollectionTimeline from '@/components/organisms/input/CollectionTimeline'
import LiveLogStream from '@/components/organisms/input/LiveLogStream'

const logger = getLogger()

function parseSymbols(text: string): string[] {
  return text
    .split(/[\n,;、]/)
    .map((s) => s.trim().toUpperCase())
    .filter(Boolean)
}

/** 从 DEFAULT_DIMENSIONS 动态构建维度选项（L24 修复：原硬编码仅 2 项） */
const DIMENSION_OPTIONS = DEFAULT_DIMENSIONS.map((dim) => ({
  value: dim.code,
  label: dim.name,
})) as readonly { value: TraceDimension; label: string }[]

export default function DataTestPanel(): React.JSX.Element {
  const store = useDataTestStore()
  const runtime = useCollectionRuntimeStore()
  const configStore = useSevenDimConfigStore()

  const config = useMemo(() => configStore.getCollectionConfig(), [configStore])
  const traceSpans = useMemo(
    () => Object.values(runtime.traceSpans ?? {}),
    [runtime.traceSpans],
  )

  const handleCheckHealth = async (): Promise<void> => {
    logger.info('[DataTestPanel] 检查采集服务健康状态')
    try {
      await store.checkHealth()
    } catch (err) {
      logger.error('[DataTestPanel] 健康检查异常', { error: err })
    }
  }

  const handleRunSingleTrace = async (): Promise<void> => {
    logger.info('[DataTestPanel] 运行单链路测试', {
      dimension: store.selectedDimension,
      symbol: store.singleSymbol,
    })
    try {
      await store.runSingleTrace(config)
    } catch (err) {
      logger.error('[DataTestPanel] 单链路测试异常', { error: err })
    }
  }

  const handleRunBatchTrace = async (): Promise<void> => {
    logger.info('[DataTestPanel] 运行批量链路测试', {
      symbolCount: parseSymbols(store.batchText).length,
    })
    try {
      await store.runBatchTrace(config)
    } catch (err) {
      logger.error('[DataTestPanel] 批量链路测试异常', { error: err })
    }
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle>数据采集测试</CardTitle>
      </CardHeader>
      <CardContent className="space-y-6">
        {/* 服务健康 */}
        <div className="flex items-center gap-3 rounded-md border p-3">
          <span className="text-sm text-muted-foreground">采集服务状态：</span>
          {store.health === null ? (
            <Badge variant="outline">未检查</Badge>
          ) : store.health ? (
            <Badge className={`${COLOR_TOKENS.success.bgClass} text-white`}>已连接</Badge>
          ) : (
            <Badge variant="destructive">未连接</Badge>
          )}
          <Button size="sm" variant="secondary" onClick={() => void handleCheckHealth()} disabled={store.checking}>
            {store.checking ? '检查中...' : '检查连接'}
          </Button>
        </div>

        {/* 质量指标 */}
        <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
          <StatCard label="采集成功率" value={`${runtime.stats.successRate}%`} color={COLOR_TOKENS.success} />
          <StatCard label="平均延迟" value={`${runtime.stats.avgLatency}ms`} color={COLOR_TOKENS.info} />
          <StatCard label="降级次数" value={String(runtime.stats.fallbackCount)} color={COLOR_TOKENS.warning} />
          <StatCard label="写入成功率" value={`${runtime.stats.writeRate}%`} color={COLOR_TOKENS.success} />
        </div>

        {/* 单链路测试 */}
        <div className="space-y-2">
          <h4 className="text-sm font-semibold">单链路测试</h4>
          <div className="flex flex-wrap gap-2">
            <Input
              className="min-w-[160px] flex-1"
              placeholder="股票代码，如 600519.SH"
              value={store.singleSymbol}
              onChange={(e) => store.setSingleSymbol(e.target.value)}
            />
            <Select
              value={store.selectedDimension}
              onValueChange={(value) => store.setSelectedDimension(value as TraceDimension)}
              className="h-9 w-40 text-sm"
            >
              {DIMENSION_OPTIONS.map((opt) => (
                <SelectItem key={opt.value} value={opt.value}>
                  {opt.label}
                </SelectItem>
              ))}
            </Select>
            <Button size="sm" onClick={() => void handleRunSingleTrace()} disabled={store.singleStatus === 'running'}>
              {store.singleStatus === 'running' ? '运行中...' : '运行链路测试'}
            </Button>
          </div>
          {store.singleStatus === 'running' && (
            <div className="space-y-2">
              <Skeleton className="h-4 w-full" />
              <Skeleton className="h-4 w-3/4" />
              <Skeleton className="h-4 w-1/2" />
            </div>
          )}
          {store.singleStatus === 'done' && store.singleResult && (
            <pre className="max-h-60 overflow-auto rounded-md border bg-muted p-3 text-xs">
              {store.singleResult}
            </pre>
          )}
        </div>

        {/* 批量采集测试 */}
        <div className="space-y-2">
          <h4 className="text-sm font-semibold">批量采集测试（含进度）</h4>
          <textarea
            className="min-h-[100px] w-full rounded-md border bg-background p-3 text-sm"
            placeholder="每行一个股票代码，如：&#10;600519,贵州茅台&#10;000001,平安银行"
            value={store.batchText}
            onChange={(e) => store.setBatchText(e.target.value)}
          />
          <Button
            onClick={() => void handleRunBatchTrace()}
            disabled={store.batchRunning || parseSymbols(store.batchText).length === 0}
          >
            {store.batchRunning ? '采集中...' : '开始批量采集测试'}
          </Button>

          {store.batchRunning && (
            <div className="space-y-1">
              <div className="flex justify-between text-xs text-muted-foreground">
                <span>总体进度</span>
                <span>{store.progress}%</span>
              </div>
              <div className="h-2 w-full overflow-hidden rounded-full bg-muted">
                <div
                  className="h-full bg-primary transition-[width]"
                  style={{ width: `${store.progress}%` }}
                />
              </div>
            </div>
          )}

          {(store.tasks ?? []).length > 0 && (
            <div className="max-h-60 overflow-auto rounded-md border">
              <table className="w-full text-sm">
                <thead className="bg-muted">
                  <tr>
                    <th className="px-3 py-1 text-left">代码</th>
                    <th className="px-3 py-1 text-left">状态</th>
                    <th className="px-3 py-1 text-left">结果</th>
                  </tr>
                </thead>
                <tbody>
                  {(store.tasks ?? []).map((task) => (
                    <tr key={task.symbol} className="border-t">
                      <td className="px-3 py-1">{task.symbol}</td>
                      <td className="px-3 py-1">
                        {task.status === 'success' && (
                          <Badge className={`${COLOR_TOKENS.success.bgClass} text-white`}>成功</Badge>
                        )}
                        {task.status === 'error' && <Badge variant="destructive">失败</Badge>}
                        {task.status === 'running' && <Badge variant="outline">采集中</Badge>}
                        {task.status === 'pending' && <Badge variant="outline">等待中</Badge>}
                      </td>
                      <td className="px-3 py-1 text-xs text-muted-foreground">{task.message}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>

        {/* 链路时间线 */}
        <CollectionTimeline spans={traceSpans} />

        {/* 实时日志流 */}
        <LiveLogStream logs={runtime.logs} onClear={() => runtime.clearLogs()} />
      </CardContent>
    </Card>
  )
}

function StatCard({
  label,
  value,
  color,
}: {
  label: string
  value: string
  color: { tailwind: string }
}): React.JSX.Element {
  return (
    <div className="rounded-md border p-3">
      <p className="text-xs text-muted-foreground">{label}</p>
      <p className={`text-lg font-bold ${color.tailwind}`}>{value}</p>
    </div>
  )
}

import React, { useEffect, useRef, useState, Suspense } from 'react'
import { useLocation } from 'react-router'
import InputDashboard from './InputDashboard'
import LocalKnowledgePage from '@/pages/input/LocalKnowledgePage'
import CollectionMonitorPanel from './CollectionMonitorPanel'
import CollectionStrategyPage from './CollectionStrategyPage'
import { InputFlowErrorBoundary } from '@/components/organisms/input/InputFlowErrorBoundary'
import { getLogger } from '@/lib/logger'

// 子页面懒加载（保留旧路由兼容）
const PoolBoardPage = React.lazy(() => import('@/pages/analysis/PoolBoardPage'))

interface InputRoute {
  path: string
  branch: string
  componentName: string
  exact?: boolean
  component: React.ReactNode
  fallback: string
}

const INPUT_ROUTES: InputRoute[] = [
  // 合并后的新路由
  { path: '/input/collection-monitor', branch: 'collection-monitor', componentName: 'CollectionMonitorPanel', component: <CollectionMonitorPanel />, fallback: '加载采集监控台中...' },
  { path: '/input/collection-strategy', branch: 'collection-strategy', componentName: 'CollectionStrategyPage', component: <CollectionStrategyPage />, fallback: '加载采集策略配置中...' },
  // 保留旧路由兼容（重定向到合并组件）
  { path: '/input/data-test', branch: 'data-test', componentName: 'CollectionMonitorPanel', component: <CollectionMonitorPanel />, fallback: '' },
  { path: '/input/collect-tasks', branch: 'collect-tasks', componentName: 'CollectionMonitorPanel', component: <CollectionMonitorPanel />, fallback: '' },
  { path: '/input/seven-dim', branch: 'seven-dim', componentName: 'CollectionStrategyPage', component: <CollectionStrategyPage />, fallback: '加载采集策略配置中...' },
  { path: '/input/fetcher-config', branch: 'fetcher-config', componentName: 'CollectionStrategyPage', component: <CollectionStrategyPage />, fallback: '加载采集策略配置中...' },
  // 其他保留路由
  { path: '/input/local-knowledge', branch: 'local-knowledge', componentName: 'LocalKnowledgePage', component: <LocalKnowledgePage />, fallback: '' },
  { path: '/input/pool-board', branch: 'pool-board', componentName: 'PoolBoardPage', component: <PoolBoardPage />, fallback: '加载股票池看板中...' },
]

function matchInputRoute(path: string): InputRoute {
  for (const route of INPUT_ROUTES) {
    if (route.exact === false) {
      if (path === route.path || path.startsWith(route.path + '/')) return route
    } else if (path === route.path) {
      return route
    }
  }
  return { path: '', branch: 'default', componentName: 'InputDashboard', component: null, fallback: '' }
}

const logger = getLogger()

/**
 * 输入舱子路由分发
 *
 * @description
 * 使用 useLocation + 条件渲染替代嵌套 <Routes>。
 *
 * 根因：React Router v7 在 descendant <Routes> 场景下，绝对路径匹配行为
 * 与 v6 不一致。当 App.tsx 顶层已通过 <Route path="/input"> 匹配并渲染
 * PortalShell → InputApp 时，InputApp 内部的 <Routes path="/input/...">
 * 不会再次匹配当前 URL（证据：main 内容为空，子面板 chunk 未请求）。
 *
 * 修复方案：直接读取 location.pathname 进行条件渲染，绕过 descendant
 * Routes 的路径匹配问题。新增子面板仅需在 INPUT_ROUTES 中追加条目。
 *
 * 路由映射：
 * - /input/data-test       → DataTestPanel
 * - /input/local-knowledge → LocalKnowledgePage
 * - /input/seven-dim       → SevenDimConfigPage（懒加载）
 * - /input/fetcher-config  → FetcherConfigPage（懒加载）
 * - /input/collect-tasks   → CollectTaskPage（懒加载）
 * - /input/pool-board      → PoolBoardPage（懒加载）
 * - /input/bulk-import     → 已整合至 InputDashboard（fallback 到录入看板）
 * - /input/hot-sectors     → 已整合至 InputDashboard（fallback 到录入看板）
 * - /input（默认）         → InputDashboard
 */
export default function InputApp(): React.JSX.Element {
  const location = useLocation()
  const path = location.pathname
  const prevPathRef = useRef<string | null>(null)

  // 路由切换检测：仅在 pathname 变化时记录切换事件与渲染状态
  useEffect(() => {
    const prevPath = prevPathRef.current
    const isRouteChange = prevPath !== null && prevPath !== path

    if (isRouteChange) {
      logger.info('[InputApp] 路由切换', { from: prevPath, to: path })
    }

    // 计算命中的分支与组件名（仅在路径变化时记录，避免 PortalShell 重渲染导致日志噪音）
    const { branch, componentName } = matchInputRoute(path)

    logger.info('[InputApp] 渲染输入舱', {
      path,
      branch,
      component: componentName,
      isRouteChange,
    })

    prevPathRef.current = path
  }, [path])

  // 错误边界 reset key：onReset 时自增，强制 InputDashboard 重建实例清空错误态
  const [resetKey, setResetKey] = useState(0)

  const matched = matchInputRoute(path)

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-xl font-bold">输入舱</h1>
          <p className="text-sm text-muted-foreground">候选池管理 · 数据采集 · 热门板块纳入</p>
        </div>
      </div>
      <InputFlowErrorBoundary
        label="InputApp"
        onReset={() => setResetKey((k) => k + 1)}
      >
        {matched.component ? (
          <Suspense fallback={<div className="p-4 text-sm text-muted-foreground">{matched.fallback}</div>}>
            {matched.component}
          </Suspense>
        ) : (
          <InputDashboard key={resetKey} />
        )}
      </InputFlowErrorBoundary>
    </div>
  )
}

/**
 * @fileoverview InputDashboard 数据层 Hook — 状态管理、副作用、回调逻辑
 * @module apps/input/hooks/useInputDashboardData
 */

import { useEffect, useMemo, useRef, useState, useCallback } from 'react'
import { checkFetcherHealth } from '@/services/fetcher/fetcherService'
import { fetchBasicDataUseCase } from '@/services/useCase/fetcherOrchestrator.useCase'
import { useIntentionPoolStore, getIntentionPoolGroups } from '@/store/intentionPoolStore'
import { getLogger } from '@/lib/logger'
import { createDebugLogger } from '@/lib/debugToolkit'
import { eventBus } from '@/lib/eventBus'
import type { PoolItem } from '@/types/modules/pool.types'

const logger = getLogger()
/** 采集状态 Badge 三态切换的 Debug 日志（控制台筛选 [CollectBadge]） */
const debug = createDebugLogger('CollectBadge')

/** 统计概览数据 */
export interface DashboardStats {
  total: number
  withPrice: number
  coverage: number
}

/**
 * InputDashboard 数据层 Hook
 *
 * 封装意向候选池的状态读取、采集/删除/勾选等业务回调，
 * 使主组件聚焦于 UI 渲染。
 */
export function useInputDashboardData() {
  // 从 intentionPoolStore 获取状态
  const items = useIntentionPoolStore((s) => s.items)
  const loading = useIntentionPoolStore((s) => s.loading)
  const error = useIntentionPoolStore((s) => s.error)
  const refresh = useIntentionPoolStore((s) => s.refresh)

  // 本地 UI 状态
  const [fetcherOk, setFetcherOk] = useState<boolean | null>(null)
  const [collectingSymbols, setCollectingSymbols] = useState<Set<string>>(new Set())

  // 勾选状态：已选中的标的代码集合（用于批量删除）
  const [selectedSymbols, setSelectedSymbols] = useState<string[]>([])
  const selectAllRef = useRef<HTMLInputElement>(null)

  // 初始化加载
  useEffect(() => {
    logger.info('[InputDashboard] 初始化，加载股票池数据')
    void refresh()
  }, [refresh])

  // 批量导入完成后自动刷新清单，确保页面完整覆盖所有已输入数据
  useEffect(() => {
    const off = eventBus.on('BATCH_IMPORT_COMPLETED', () => {
      logger.info('[InputDashboard] 收到 BATCH_IMPORT_COMPLETED，刷新清单')
      void refresh()
    })
    return off
  }, [refresh])

  // 分组列表：依赖 items，items 变化时重新计算
  const allGroups = useMemo(() => getIntentionPoolGroups(), [items])
  const allStocks: PoolItem[] = items

  // 全选框的半选（indeterminate）状态
  useEffect(() => {
    if (selectAllRef.current) {
      selectAllRef.current.indeterminate =
        selectedSymbols.length > 0 && selectedSymbols.length < allStocks.length
    }
  }, [selectedSymbols.length, allStocks.length])

  const handleCollectStock = useCallback(async (symbol: string): Promise<void> => {
    debug.log('handleCollectStock 开始', {
      symbol,
      timestamp: Date.now(),
      currentCollecting: Array.from(collectingSymbols),
    })
    setCollectingSymbols((prev) => {
      const next = new Set(prev).add(symbol)
      debug.log('setCollectingSymbols ADD', {
        symbol,
        newSet: Array.from(next),
        size: next.size,
      })
      return next
    })
    try {
      const result = await fetchBasicDataUseCase({ symbol })
      debug.log('handleCollectStock 采集结果', {
        symbol,
        success: result.success,
        error: result.error,
        hasPrice: result.data?.price,
        elapsedMs: result.data ? 'completed' : 'n/a',
      })
      if (!result.success) {
        logger.warn('[InputDashboard] 采集失败', { symbol, error: result.error })
      }
      debug.log('handleCollectStock 刷新前', { symbol })
      await refresh()
      const updated = useIntentionPoolStore.getState().items.find((s) => s.symbol === symbol)
      debug.log('handleCollectStock 刷新后', {
        symbol,
        hasPrice: updated?.price !== undefined,
        price: updated?.price,
      })
    } catch (err) {
      logger.error('[InputDashboard] 采集异常', {
        symbol,
        error: err instanceof Error ? err.message : String(err),
      })
    } finally {
      setCollectingSymbols((prev) => {
        const next = new Set(prev)
        next.delete(symbol)
        debug.log('setCollectingSymbols REMOVE', {
          symbol,
          newSet: Array.from(next),
          size: next.size,
        })
        return next
      })
    }
  }, [refresh, collectingSymbols])

  const handleCollectAll = useCallback(async (): Promise<void> => {
    const toCollect = allStocks.filter((s) => s.price === undefined)
    if (toCollect.length === 0) {
      debug.log('handleCollectAll 无待采集标的')
      return
    }

    const symbolsToCollect = toCollect.map((s) => s.symbol)
    debug.log('handleCollectAll 开始并发采集', {
      totalToCollect: toCollect.length,
      symbols: symbolsToCollect,
      timestamp: Date.now(),
    })

    // 并行采集：使用 Promise.allSettled 并发执行
    setCollectingSymbols(new Set(symbolsToCollect))
    debug.log('handleCollectAll 已设置 collectingSymbols', {
      count: symbolsToCollect.length,
    })

    try {
      const results = await Promise.allSettled(
        toCollect.map(async (item, idx) => {
          debug.log('并发采集子任务启动', {
            symbol: item.symbol,
            taskIndex: idx,
            timestamp: Date.now(),
          })
          const result = await fetchBasicDataUseCase({ symbol: item.symbol })
          debug.log('并发采集子任务完成', {
            symbol: item.symbol,
            taskIndex: idx,
            success: result.success,
            elapsedMs: Date.now(),
          })
          // 立即移除该 symbol，让 Badge 从「采集中」及时切换为「已采/待采」，
          // 避免先完成的股票被卡在「采集中」状态等待最慢的子任务。
          setCollectingSymbols((prev) => {
            const next = new Set(prev)
            next.delete(item.symbol)
            debug.log('子任务完成即移除 collectingSymbol', {
              symbol: item.symbol,
              remaining: next.size,
            })
            return next
          })
          return { symbol: item.symbol, result }
        }),
      )
      const successCount = results.filter(
        (r) => r.status === 'fulfilled' && r.value.result.success,
      ).length
      const failCount = results.length - successCount
      const detail = results.map((r, i) => ({
        symbol: symbolsToCollect[i],
        status: r.status,
        success: r.status === 'fulfilled' ? r.value.result.success : false,
        error: r.status === 'rejected' ? String(r.reason) : r.status === 'fulfilled' ? r.value.result.error : null,
      }))
      debug.log('handleCollectAll 并发采集汇总', {
        total: toCollect.length,
        successCount,
        failCount,
        detail,
      })
      logger.info('[InputDashboard] 批量采集完成', { successCount, failCount, total: toCollect.length })
      debug.log('handleCollectAll 刷新前候选池', {
        poolSize: allStocks.length,
      })
      await refresh()
      debug.log('handleCollectAll 刷新后候选池', {
        poolSize: useIntentionPoolStore.getState().items.length,
        withPrice: useIntentionPoolStore.getState().items.filter((s) => s.price !== undefined).length,
      })
    } catch (err) {
      logger.error('[InputDashboard] 批量采集异常', {
        error: err instanceof Error ? err.message : String(err),
      })
    } finally {
      setCollectingSymbols(new Set())
      debug.log('handleCollectAll 已清除 collectingSymbols')
    }
  }, [allStocks, refresh])

  const handleDeleteStock = useCallback(async (symbol: string): Promise<void> => {
    const store = useIntentionPoolStore.getState()
    try {
      const deleted = await store.deleteItem(symbol)
      if (deleted) {
        setSelectedSymbols((prev) => prev.filter((s) => s !== symbol))
        await refresh()
      }
    } catch (err) {
      logger.error('[InputDashboard] 移除异常', {
        symbol,
        error: err instanceof Error ? err.message : String(err),
      })
    }
  }, [refresh])

  // ── 勾选 / 批量删除 ──
  const handleToggleSelect = useCallback((symbol: string): void => {
    setSelectedSymbols((prev) =>
      prev.includes(symbol) ? prev.filter((s) => s !== symbol) : [...prev, symbol],
    )
  }, [])

  const handleToggleSelectAll = useCallback((checked: boolean): void => {
    setSelectedSymbols(checked ? allStocks.map((s) => s.symbol) : [])
  }, [allStocks])

  const handleBatchDelete = useCallback(async (): Promise<void> => {
    if (selectedSymbols.length === 0) return
    const store = useIntentionPoolStore.getState()
    try {
      const count = await store.deleteItems(selectedSymbols)
      setSelectedSymbols([])
      if (count === 0) {
        logger.warn('[InputDashboard] 批量删除失败', { symbols: selectedSymbols })
      }
    } catch (err) {
      logger.error('[InputDashboard] 批量删除异常', {
        error: err instanceof Error ? err.message : String(err),
      })
    }
  }, [selectedSymbols])

  const handleRefreshHealth = useCallback(async (): Promise<void> => {
    setFetcherOk(null)
    try {
      const result = await checkFetcherHealth()
      setFetcherOk(result.ok)
    } catch (err) {
      setFetcherOk(false)
      logger.error('[InputDashboard] 采集服务检查异常', {
        error: err instanceof Error ? err.message : String(err),
      })
    }
  }, [])

  const stats = useMemo<DashboardStats>(() => {
    const total = allStocks.length
    const withPrice = allStocks.filter((s) => s.price !== undefined).length
    const coverage = total > 0 ? Math.round((withPrice / total) * 100) : 0
    return { total, withPrice, coverage }
  }, [allStocks])

  return {
    items,
    loading,
    error,
    refresh,
    allGroups,
    allStocks,
    fetcherOk,
    collectingSymbols,
    selectedSymbols,
    selectAllRef,
    stats,
    handleCollectStock,
    handleCollectAll,
    handleDeleteStock,
    handleToggleSelect,
    handleToggleSelectAll,
    handleBatchDelete,
    handleRefreshHealth,
  }
}

import React, { useEffect, useRef, Suspense } from 'react'
