/**
 * 交易舱子路由分发
 *
 * @description
 * 使用 useLocation + 条件渲染实现子路由分发。
 * 新增子页面仅需在 TRADING_ROUTES 中追加条目并添加对应 React.lazy 导入。
 *
 * 路由映射：
 * - /trading/strategy-snapshots → StrategySnapshotPage
 * - /trading/holdings          → HoldingsPage
 * - /trading/execution-plans   → ExecutionPlanPanel
 * - /trading（默认）           → 交易看板（TradingDashboard）
 */
export default function TradingApp(): React.JSX.Element {
  const location = useLocation()
  const path = location.pathname
  const prevPathRef = useRef<string | null>(null)

  // 从 tradingStore 获取初始化日志所需状态
  const stocks = useTradingStore((s) => s.stocks)
  const orders = useTradingStore((s) => s.orders)
  const signals = useTradingStore((s) => s.signals)

  // 路由切换检测：仅在 pathname 变化时记录切换事件与渲染状态
  useEffect(() => {
    const prevPath = prevPathRef.current
    const isRouteChange = prevPath !== null && prevPath !== path

    if (isRouteChange) {
      logger.info('[TradingApp] 路由切换', { from: prevPath, to: path })
    }

    // 计算命中的分支与组件名
    const { branch, componentName } = matchTradingRoute(path)

    logger.info('[TradingApp] 渲染交易舱', {
      path,
      branch,
      component: componentName,
      isRouteChange,
    })

    prevPathRef.current = path
  }, [path])

  // 组件初始化日志
  useEffect(() => {
    logger.info('[TradingApp] 组件初始化', {
      stocksCount: stocks.length,
      ordersCount: orders.length,
      signalsCount: signals.length,
    })
  }, []) // eslint-disable-line react-hooks/exhaustive-deps

  const matched = matchTradingRoute(path)

  return (
    <div className="space-y-4 p-4">
      {matched.component != null ? (
        <Suspense fallback={<div className="p-4 text-sm text-muted-foreground">{matched.fallback}</div>}>
          {matched.component}
        </Suspense>
      ) : (
        <TradingDashboard />
      )}
    </div>
  )
}

import React, { useState } from 'react'
import { cn } from '@/lib/utils'
import { Card, CardContent, CardHeader } from '@/components/atoms/Card'
import { Badge } from '@/components/atoms/Badge'
import { Button } from '@/components/atoms/Button'
import { PhaseStepper } from './PhaseStepper'
import type { ExecutionPlan, ExecutionPhase, RiskCheckItem } from '@/data/types'
import { ChevronDown, ChevronUp, ShieldAlert, ShieldCheck, Info } from 'lucide-react'
import { COLOR_SHADES } from '@/constants/theme.tokens'

export interface ExecutionPlanCardProps {
  plan: ExecutionPlan
  onConfirm?: (planId: string) => void
  onExecute?: (planId: string) => void
  onCancel?: (planId: string) => void
  onReview?: (planId: string) => void
}

const PHASE_BADGE_COLORS: Record<ExecutionPhase, string> = {
  plan: 'bg-info/10 text-info',
  confirmed: 'bg-info/10 text-info',
  pending: 'bg-warning/10 text-warning',
  executed: 'bg-success/10 text-success',
  cancelled: 'bg-destructive/10 text-destructive',
  reviewed: 'bg-info/10 text-info',
}

const PHASE_LABELS: Record<ExecutionPhase, string> = {
  plan: '计划',
  confirmed: '已确认',
  pending: '执行中',
  executed: '已执行',
  cancelled: '已取消',
  reviewed: '已复盘',
}

function formatRelativeTime(timestamp: number): string {
  const diff = Date.now() - timestamp
  const seconds = Math.floor(diff / 1000)
  const minutes = Math.floor(seconds / 60)
  const hours = Math.floor(minutes / 60)
  const days = Math.floor(hours / 24)

  if (days > 0) return `${days}天前`
  if (hours > 0) return `${hours}小时前`
  if (minutes > 0) return `${minutes}分钟前`
  return '刚刚'
}

function getStepperPhase(plan: ExecutionPlan): ExecutionPhase {
  if (plan.phase !== 'cancelled') return plan.phase
  // 根据时间戳推断取消前最后到达的阶段
  if ((plan.executedAt ?? 0) > 0) return 'pending'
  if ((plan.confirmedAt ?? 0) > 0) return 'confirmed'
  return 'plan'
}

export function ExecutionPlanCard({
  plan,
  onConfirm,
  onExecute,
  onCancel,
  onReview,
}: ExecutionPlanCardProps): React.JSX.Element {
  const [riskExpanded, setRiskExpanded] = useState(false)

  const directionLabel = plan.direction === 'buy' ? '买入' : '卖出'
  const directionClass =
    plan.direction === 'buy'
      ? `${COLOR_SHADES.green[100]} ${COLOR_SHADES.green[800]}`
      : `${COLOR_SHADES.red[100]} ${COLOR_SHADES.red[800]}`

  const phaseClass = PHASE_BADGE_COLORS[plan.phase]
  const stepperPhase = getStepperPhase(plan)
  const isCancelled = plan.phase === 'cancelled'

  // 操作按钮可见性
  const canConfirm = plan.phase === 'plan' && !!onConfirm
  const canExecute = (plan.phase === 'plan' || plan.phase === 'confirmed') && !!onExecute
  const canCancel =
    (plan.phase === 'plan' || plan.phase === 'confirmed' || plan.phase === 'pending') && !!onCancel
  const canReview =
    (plan.phase === 'executed' || plan.phase === 'cancelled') && !!onReview

  const riskChecks = plan.risk?.checks ?? []

  return (
    <Card className="overflow-hidden">
      <CardHeader className="pb-2">
        <div className="flex items-center justify-between flex-wrap gap-2">
          <div className="flex items-center gap-2">
            <span className="font-mono font-semibold text-sm">{plan.symbol}</span>
            <Badge className={cn(directionClass)}>{directionLabel}</Badge>
            <Badge className={cn(phaseClass)}>{PHASE_LABELS[plan.phase]}</Badge>
          </div>
          <span className="text-xs text-muted-foreground">
            置信度 {(plan.confidence * 100).toFixed(0)}%
          </span>
        </div>
      </CardHeader>

      <CardContent className="space-y-3 pt-0">
        {/* 状态机步骤条 */}
        <PhaseStepper
          phase={stepperPhase}
          cancelled={isCancelled}
          result={plan.result}
        />

        {/* 详情区 */}
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-2 text-xs">
          <div className="rounded-md border p-2">
            <p className="text-muted-foreground">数量 / 仓位</p>
            <p className="font-medium">
              {plan.sizing ? `${plan.sizing.quantity}股 / ${(plan.sizing.positionPct * 100).toFixed(1)}%` : '—'}
            </p>
          </div>
          <div className="rounded-md border p-2">
            <p className="text-muted-foreground">风控检查</p>
            <div className="flex items-center gap-1 font-medium">
              {plan.risk ? (
                <>
                  {plan.risk.passed ? (
                    <ShieldCheck className={`h-3.5 w-3.5 ${COLOR_SHADES.green[600]}`} />
                  ) : (
                    <ShieldAlert className={`h-3.5 w-3.5 ${COLOR_SHADES.red[600]}`} />
                  )}
                  <span className={plan.risk.passed ? COLOR_SHADES.green[700] : COLOR_SHADES.red[700]}>
                    {plan.risk.passed ? '通过' : '未通过'}
                  </span>
                  <span className="text-muted-foreground">({plan.risk.checks.length}项)</span>
                </>
              ) : (
                <span>—</span>
              )}
            </div>
          </div>
          <div className="rounded-md border p-2">
            <p className="text-muted-foreground">订单号</p>
            <p className="font-medium truncate">{plan.orderId ?? '—'}</p>
          </div>
        </div>

        {/* 风控明细可展开 */}
        {riskChecks.length > 0 && (
          <div>
            <button
              type="button"
              onClick={() => setRiskExpanded((v) => !v)}
              className="flex items-center gap-1 text-xs text-muted-foreground hover:text-foreground transition-colors"
            >
              {riskExpanded ? <ChevronUp className="h-3.5 w-3.5" /> : <ChevronDown className="h-3.5 w-3.5" />}
              风控明细 ({riskChecks.length}项)
            </button>
            {riskExpanded && (
              <div className="mt-2 space-y-1.5">
                {riskChecks.map((check: RiskCheckItem, idx: number) => (
                  <div
                    key={idx}
                    className={cn(
                      'flex items-start gap-1.5 rounded-md border px-2 py-1.5 text-xs',
                      check.severity === 'blocker' && 'bg-destructive/10 bg-destructive/20 text-destructive',
                      check.severity === 'warning' && 'bg-warning/10 bg-warning/20 text-warning',
                      check.severity === 'info' && 'bg-muted/50 bg-muted text-muted-foreground'
                    )}
                  >
                    {check.severity === 'blocker' && <ShieldAlert className={`h-3.5 w-3.5 ${COLOR_SHADES.red[600]} mt-0.5 shrink-0`} />}
                    {check.severity === 'warning' && <ShieldCheck className={`h-3.5 w-3.5 ${COLOR_SHADES.yellow[600]} mt-0.5 shrink-0`} />}
                    {check.severity === 'info' && <Info className={`h-3.5 w-3.5 ${COLOR_SHADES.gray[500]} mt-0.5 shrink-0`} />}
                    <div>
                      <span className="font-medium">{check.name}:</span>{' '}
                      <span>{check.message}</span>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {/* 错误信息 */}
        {(plan.errorMessage ?? '') !== '' && (
          <p className={`text-xs ${COLOR_SHADES.red[600]} ${COLOR_SHADES.red[50]} rounded-md px-2 py-1.5 border ${COLOR_SHADES.red[200]}`}>
            {plan.errorMessage}
          </p>
        )}

        {/* 操作按钮 */}
        <div className="flex flex-wrap gap-2">
          {canConfirm && (
            <Button size="sm" onClick={() => onConfirm?.(plan.id)}>
              确认
            </Button>
          )}
          {canExecute && (
            <Button size="sm" onClick={() => onExecute?.(plan.id)}>
              执行
            </Button>
          )}
          {canCancel && (
            <Button variant="danger" size="sm" onClick={() => onCancel?.(plan.id)}>
              取消
            </Button>
          )}
          {canReview && (
            <Button variant="secondary" size="sm" onClick={() => onReview?.(plan.id)}>
              复盘
            </Button>
          )}
        </div>

        {/* 底部时间 */}
        <div className="flex items-center justify-between text-[10px] text-muted-foreground pt-1 border-t">
          <span>创建于 {formatRelativeTime(plan.createdAt)}</span>
          {plan.accountType && (
            <Badge variant="outline" className="text-[10px] px-1.5 py-0">
              {plan.accountType === 'paper' ? '模拟盘' : plan.accountType === 'real' ? '实盘' : plan.accountType}
            </Badge>
          )}
        </div>
      </CardContent>
    </Card>
  )
}

import React, { useEffect, useMemo, useState } from 'react'
import { cn } from '@/lib/utils'
import { getLogger } from '@/lib/logger'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/atoms/Card'
import { Badge } from '@/components/atoms/Badge'
import { Button } from '@/components/atoms/Button'
import { EmptyState } from '@/components/molecules/EmptyState'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/molecules/Tabs'
import { useExecutionStore } from '@/store/executionStore'
import { initExecutionStoreSubscriptions } from '@/store/executionStoreSubscriptions'
import { ExecutionPlanCard } from '../components/ExecutionPlanCard'
import type { ExecutionPlan } from '@/data/types'
import { RefreshCw } from 'lucide-react'

type FilterTab = 'all' | 'active' | 'completed' | 'cancelled' | 'reviewed'

const logger = getLogger()

const TAB_LABELS: Record<FilterTab, string> = {
  all: '全部',
  active: '活跃',
  completed: '已完成',
  cancelled: '已取消',
  reviewed: '已复盘',
}

function isToday(timestamp: number): boolean {
  const d = new Date(timestamp)
  const now = new Date()
  return (
    d.getFullYear() === now.getFullYear() &&
    d.getMonth() === now.getMonth() &&
    d.getDate() === now.getDate()
  )
}

function filterPlans(plans: ExecutionPlan[], tab: FilterTab): ExecutionPlan[] {
  switch (tab) {
    case 'active':
      return plans.filter((p) => p.phase === 'plan' || p.phase === 'confirmed' || p.phase === 'pending')
    case 'completed':
      return plans.filter((p) => p.phase === 'executed')
    case 'cancelled':
      return plans.filter((p) => p.phase === 'cancelled')
    case 'reviewed':
      return plans.filter((p) => p.phase === 'reviewed')
    default:
      return plans
  }
}

export function ExecutionPlanPanel(): React.JSX.Element {
  const [activeTab, setActiveTab] = useState<FilterTab>('all')

  const plans = useExecutionStore((s) => s.plans)
  const activePlans = useExecutionStore((s) => s.activePlans)
  const loading = useExecutionStore((s) => s.loading)
  const isRefreshing = useExecutionStore((s) => s.isRefreshing)
  const refresh = useExecutionStore((s) => s.refresh)
  const confirmPlan = useExecutionStore((s) => s.confirmPlan)
  const executePlan = useExecutionStore((s) => s.executePlan)
  const cancelPlan = useExecutionStore((s) => s.cancelPlan)
  const markReviewed = useExecutionStore((s) => s.markReviewed)

  useEffect(() => {
    const snapshot = useExecutionStore.getState()
    logger.info('[ExecutionPlanPanel] 挂载，开始初始化订阅', {
      planCount: snapshot.plans.length,
      activePlanCount: snapshot.activePlans.length,
    })
    const cleanup = initExecutionStoreSubscriptions()
    logger.info('[ExecutionPlanPanel] 订阅初始化完成，触发首次刷新')
    void refresh()
    return () => {
      logger.info('[ExecutionPlanPanel] 卸载，清理订阅')
      cleanup()
    }
  }, [refresh])

  const filteredPlans = useMemo(() => filterPlans(plans, activeTab), [plans, activeTab])

  const stats = useMemo(() => {
    const active = activePlans.length
    const pendingConfirm = plans.filter((p) => p.phase === 'plan').length
    const todayExecuted = plans.filter(
      (p) => p.phase === 'executed' && p.executedAt && isToday(p.executedAt)
    ).length
    return { active, pendingConfirm, todayExecuted }
  }, [plans, activePlans])

  return (
    <Card>
      <CardHeader>
        <div className="flex items-center justify-between flex-wrap gap-2">
          <div className="flex items-center gap-2">
            <CardTitle>执行计划</CardTitle>
            {activePlans.length > 0 && (
              <Badge variant="default">{activePlans.length}</Badge>
            )}
          </div>
          <Button
            variant="secondary"
            size="sm"
            onClick={() => void refresh()}
            disabled={isRefreshing}
          >
            <RefreshCw className={cn('h-3.5 w-3.5 mr-1', isRefreshing && 'animate-spin')} />
            {isRefreshing ? '刷新中...' : '刷新'}
          </Button>
        </div>
      </CardHeader>

      <CardContent className="space-y-4">
        {/* 统计栏 */}
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-2">
          <div className="rounded-md border p-2 text-center">
            <p className="text-xs text-muted-foreground">活跃</p>
            <p className="text-lg font-semibold">{stats.active}</p>
          </div>
          <div className="rounded-md border p-2 text-center">
            <p className="text-xs text-muted-foreground">待确认</p>
            <p className="text-lg font-semibold">{stats.pendingConfirm}</p>
          </div>
          <div className="rounded-md border p-2 text-center">
            <p className="text-xs text-muted-foreground">今日执行</p>
            <p className="text-lg font-semibold">{stats.todayExecuted}</p>
          </div>
        </div>

        {/* 筛选栏 */}
        <Tabs value={activeTab} onValueChange={(v) => setActiveTab(v as FilterTab)}>
          <TabsList className="w-full">
            {(Object.keys(TAB_LABELS) as FilterTab[]).map((tab) => (
              <TabsTrigger key={tab} value={tab} className="flex-1">
                {TAB_LABELS[tab]}
                <span className="ml-1 text-[10px] text-muted-foreground">
                  ({filterPlans(plans, tab).length})
                </span>
              </TabsTrigger>
            ))}
          </TabsList>

          <TabsContent value={activeTab}>
            {loading ? (
              <div className="space-y-2">
                {Array.from({ length: 3 }).map((_, i) => (
                  <div key={i} className="h-32 rounded-md border bg-muted animate-pulse" />
                ))}
              </div>
            ) : filteredPlans.length === 0 ? (
              <>
                {logger.info('[ExecutionPlanPanel] 当前标签无执行计划', { activeTab })}
                <EmptyState
                  title="暂无执行计划"
                  description="扫描信号后将自动生成"
                  className="py-8"
                />
              </>
            ) : (
              <>
                {logger.info('[ExecutionPlanPanel] 渲染执行计划列表', {
                  activeTab,
                  filteredCount: filteredPlans.length,
                })}
                <div className="grid gap-2">
                  {filteredPlans.map((plan) => (
                    <ExecutionPlanCard
                      key={plan.id}
                      plan={plan}
                      onConfirm={(plan) => void confirmPlan(plan)}
                      onExecute={(plan) => void executePlan(plan)}
                      onCancel={(plan) => void cancelPlan(plan)}
                      onReview={(plan) => void markReviewed(plan)}
                    />
                  ))}
                </div>
              </>
            )}
          </TabsContent>
        </Tabs>
      </CardContent>
    </Card>
  )
}

