/**
 * 轻量级 Markdown 渲染器
 * @description 支持标题、加粗、列表、代码块、引用、段落；未来可替换为 react-markdown
 * @remarks 禁止在组件中硬编码任何样式颜色
 */
function MarkdownRenderer({ content }: { content: string }): React.JSX.Element {
  const lines = content.split('\n')
  const elements: React.ReactNode[] = []
  let listBuffer: React.ReactNode[] | null = null
  let listOrdered = false

  const flushList = () => {
    if (!listBuffer || listBuffer.length === 0) return
    const ListTag = listOrdered ? 'ol' : 'ul'
    elements.push(
      <ListTag key={`list-${elements.length}`} className="list-inside pl-2 my-2 text-sm">
        {listBuffer}
      </ListTag>
    )
    listBuffer = null
    listOrdered = false
  }

  lines.forEach((rawLine, index) => {
    const line = rawLine.trimEnd()

    // 代码块
    if (line.startsWith('```')) {
      flushList()
      const codeLines: string[] = []
      let j = index + 1
      while (j < lines.length && !lines[j]?.trim().startsWith('```')) {
        codeLines.push(lines[j] ?? '')
        j++
      }
      elements.push(
        <pre key={`code-${index}`} className="bg-muted rounded-md p-2 my-2 text-xs overflow-auto">
          <code>{codeLines.join('\n')}</code>
        </pre>
      )
      return
    }

    // 标题
    const headerMatch = line.match(/^(#{1,3})\s+(.*)$/)
    if (headerMatch) {
      flushList()
      const level = headerMatch[1]!.length
      const text = headerMatch[2]!
      const Tag = `h${level}` as 'h1' | 'h2' | 'h3'
      const sizeClass = level === 1 ? 'text-base' : level === 2 ? 'text-sm' : 'text-xs'
      elements.push(
        <Tag key={`h-${index}`} className={`font-bold mt-3 mb-1 ${sizeClass}`}>
          {renderInline(text)}
        </Tag>
      )
      return
    }

    // 无序列表
    const ulMatch = line.match(/^[-*]\s+(.*)$/)
    if (ulMatch) {
      if (!listBuffer || listOrdered) flushList()
      listBuffer ??= []
      listOrdered = false
      listBuffer.push(<li key={`li-${index}`}>{renderInline(ulMatch[1]!)}</li>)
      return
    }

    // 有序列表
    const olMatch = line.match(/^\d+\.\s+(.*)$/)
    if (olMatch) {
      if (!listBuffer || !listOrdered) flushList()
      listBuffer ??= []
      listOrdered = true
      listBuffer.push(<li key={`li-${index}`}>{renderInline(olMatch[1]!)}</li>)
      return
    }

    // 空行
    if (line.trim() === '') {
      flushList()
      return
    }

    // 引用
    if (line.startsWith('>')) {
      flushList()
      elements.push(
        <blockquote key={`quote-${index}`} className="border-l-2 border-muted-foreground pl-3 my-2 text-xs text-muted-foreground">
          {renderInline(line.slice(1).trim())}
        </blockquote>
      )
      return
    }

    // 普通段落
    flushList()
    elements.push(
      <p key={`p-${index}`} className="text-sm my-1 leading-relaxed">
        {renderInline(line)}
      </p>
    )
  })

  flushList()
  return <div className="markdown-body">{elements}</div>
}

function renderInlineToken(token: string, key: number): React.ReactNode {
  if (token.startsWith('**') && token.endsWith('**')) {
    return <strong key={key}>{token.slice(2, -2)}</strong>
  }
  if (token.startsWith('*') && token.endsWith('*')) {
    return <em key={key}>{token.slice(1, -1)}</em>
  }
  if (token.startsWith('`') && token.endsWith('`')) {
    return (
      <code key={key} className="bg-muted px-1 rounded text-xs">
        {token.slice(1, -1)}
      </code>
    )
  }
  return token
}

/**
 * 行内 Markdown 渲染（加粗、斜体、行内代码）
 */
function renderInline(text: string): React.ReactNode {
  const parts: React.ReactNode[] = []
  const regex = /(\*\*.*?\*\*|\*.*?\*|`.*?`)/g
  let lastIndex = 0
  let match: RegExpExecArray | null

  while ((match = regex.exec(text)) !== null) {
    if (match.index > lastIndex) {
      parts.push(text.slice(lastIndex, match.index))
    }

    parts.push(renderInlineToken(match[0], match.index))
    lastIndex = regex.lastIndex
  }

  if (lastIndex < text.length) {
    parts.push(text.slice(lastIndex))
  }

  return parts
}

/**
 * 个股深度分析与市场分析聊天 Widget
 * @description 类似 ChatGPT 的交互界面，支持选择标的、清空上下文、发送问题并渲染 Markdown 回复
 * @remarks 历史数据来自 MarketData.chatHistory；发送消息通过 MarketDataProvider.sendChatMessage
 */
export default function StockChatWidget({ config, data }: StockChatWidgetProps): React.JSX.Element {
  const marketData = useMarketData()
  const sourceData = data ?? marketData.data
  const initialChat = sourceData.chatHistory

  const [target, setTarget] = useState(initialChat.target || CHAT_DEMO_TARGETS[0]!.code)
  const [messages, setMessages] = useState<ChatMessage[]>(initialChat.messages)
  const [input, setInput] = useState('')
  const [isLoading, setIsLoading] = useState(false)
  const scrollRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' })
  }, [messages])

  const handleClear = () => {
    setMessages([])
  }

  const handleSend = async () => {
    if (!input.trim() || isLoading) return

    const userMessage: ChatMessage = {
      id: `user_${nanoid(8)}`,
      role: 'user',
      content: input.trim(),
      timestamp: Date.now(),
    }

    setMessages((prev) => [...prev, userMessage])
    setInput('')
    setIsLoading(true)

    try {
      // 通过 MarketDataProvider 统一发送，避免组件直接调用后端
      const reply = await marketData.sendChatMessage(target, userMessage.content)
      setMessages((prev) => [...prev, reply])
    } catch {
      setMessages((prev) => [
        ...prev,
        {
          id: `error_${nanoid(8)}`,
          role: 'assistant',
          content: '消息发送失败，请稍后重试。',
          timestamp: Date.now(),
        },
      ])
    } finally {
      setIsLoading(false)
    }
  }

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      void handleSend()
    }
  }

  return (
    <Card className="h-full flex flex-col">
      <CardHeader className="pb-3 flex flex-row items-center justify-between">
        <CardTitle className="text-base font-semibold">{config.title}</CardTitle>
        <div className="flex items-center gap-2">
          <Select value={target} onChange={(e) => setTarget(e.target.value)} className="w-48 text-xs">
            {CHAT_DEMO_TARGETS.map((item) => (
              <SelectItem key={item.code} value={item.code}>
                {item.name} ({item.type === 'market' ? '市场' : item.code})
              </SelectItem>
            ))}
          </Select>
          <Button variant="ghost" size="sm" onClick={handleClear} title="清空上下文">
            <Trash2 className="h-4 w-4" />
          </Button>
        </div>
      </CardHeader>

      <CardContent className="flex-1 overflow-hidden">
        <div
          ref={scrollRef}
          className="h-full overflow-y-auto space-y-4 pr-2"
        >
          {messages.length === 0 && (
            <div className="text-center text-sm text-muted-foreground py-8">
              请选择标的并输入问题，开始个股/市场深度分析
            </div>
          )}
          {messages.map((msg) => (
            <div
              key={msg.id}
              className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
            >
              <div
                className={`max-w-[80%] rounded-lg px-4 py-2 text-sm ${
                  msg.role === 'user'
                    ? 'bg-primary text-primary-foreground'
                    : 'bg-muted'
                }`}
              >
                {msg.role === 'assistant' ? (
                  <MarkdownRenderer content={msg.content} />
                ) : (
                  <p className="whitespace-pre-wrap">{msg.content}</p>
                )}
                <div className="text-[10px] opacity-60 mt-1 text-right">
                  {new Date(msg.timestamp).toLocaleTimeString()}
                </div>
              </div>
            </div>
          ))}
          {isLoading && (
            <div className="flex justify-start">
              <div className="bg-muted rounded-lg px-4 py-2 text-sm">
                <span className="animate-pulse">AI 正在分析...</span>
              </div>
            </div>
          )}
        </div>
      </CardContent>

      <CardFooter className="pt-0 flex flex-col gap-2">
        <p className="text-[11px] leading-tight text-muted-foreground w-full">
          {AI_DISCLAIMER_TEXT}
        </p>
        <div className="flex w-full items-start gap-2">
          <Textarea
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="输入个股深度分析的问题，或输入市场分析的问题..."
            className="min-h-[56px] flex-1 resize-none"
            disabled={isLoading}
          />
          <Button size="sm" onClick={() => void handleSend()} disabled={isLoading || !input.trim()} className="h-14 px-4">
            <Send className="h-4 w-4" />
          </Button>
        </div>
      </CardFooter>
    </Card>
  )
}

/**
 * Button 组件单元测试
 *
 * 覆盖场景：
 * 1. 默认渲染：使用 primary variant + md size
 * 2. 6 种 variant 样式生效
 * 3. 3 种 size 样式生效
 * 4. asChild 透传 children className/ref
 * 5. click 事件冒泡
 * 6. disabled 状态
 * 7. ref 转发
 * 8. 自定义 className 合并
 * 9. isLoading 状态
 */

import { describe, expect, it, vi } from 'vitest'
import { render, screen, fireEvent } from '@testing-library/react'
import { createRef } from 'react'
import { Button } from '@/components/atoms/Button'

describe('Button', () => {
  it('默认渲染：primary variant + md size', () => {
    render(<Button>点击</Button>)
    const btn = screen.getByRole('button', { name: '点击' })
    expect(btn).toBeInTheDocument()
    expect(btn).toHaveClass('bg-primary')
    expect(btn).toHaveClass('h-10')
  })

  it('variant=secondary 应用 secondary 样式', () => {
    render(<Button variant="secondary">次要</Button>)
    expect(screen.getByRole('button')).toHaveClass('bg-secondary')
  })

  it('variant=outline 应用 outline 样式', () => {
    render(<Button variant="outline">轮廓</Button>)
    expect(screen.getByRole('button')).toHaveClass('border')
  })

  it('variant=ghost 应用 ghost 样式', () => {
    render(<Button variant="ghost">幽灵</Button>)
    expect(screen.getByRole('button')).toHaveClass('hover:bg-accent')
  })

  it('variant=danger 应用主题感知的 destructive 语义令牌', () => {
    render(<Button variant="danger">危险</Button>)
    // 迁移后：改用语义令牌 bg-destructive + text-destructive-foreground（明暗一致）
    const btn = screen.getByRole('button')
    expect(btn).toHaveClass('bg-destructive')
    expect(btn).toHaveClass('text-destructive-foreground')
  })

  it('variant=success 应用主题感知的 success 语义令牌', () => {
    render(<Button variant="success">成功</Button>)
    // 迁移后：改用语义令牌 bg-success + text-success-foreground（明暗一致）
    const btn = screen.getByRole('button')
    expect(btn).toHaveClass('bg-success')
    expect(btn).toHaveClass('text-success-foreground')
  })

  it('size=sm 应用 sm 样式', () => {
    render(<Button size="sm">小</Button>)
    expect(screen.getByRole('button')).toHaveClass('h-8')
  })

  it('size=md 应用 md 样式', () => {
    render(<Button size="md">中</Button>)
    expect(screen.getByRole('button')).toHaveClass('h-10')
  })

  it('size=lg 应用 lg 样式', () => {
    render(<Button size="lg">大</Button>)
    expect(screen.getByRole('button')).toHaveClass('h-12')
  })

  it('asChild=true 时透传 children className/ref/事件', () => {
    const handleClick = vi.fn()
    const ref = createRef<HTMLAnchorElement>()
    render(
      // asChild 时 Button 实际渲染 children，ref 指向 anchor
      <Button asChild variant="primary" size="md" onClick={handleClick} ref={ref as any}>
        <a href="/test" className="custom-link">
          链接
        </a>
      </Button>,
    )
    const anchor = screen.getByText('链接')
    expect(anchor.tagName).toBe('A')
    // Button 的 className 应合并到 a 上
    expect(anchor).toHaveClass('bg-primary')
    expect(anchor).toHaveClass('custom-link')
    expect(anchor).toHaveAttribute('href', '/test')
    // ref 应当指向 anchor
    expect(ref.current).toBeInstanceOf(HTMLAnchorElement)
    // onClick 应当透传
    fireEvent.click(anchor)
    expect(handleClick).toHaveBeenCalledTimes(1)
  })

  it('asChild=true 但 children 不是 element 时仍渲染 button', () => {
    render(
      <Button asChild>
        plain text
      </Button>,
    )
    // 当 children 不是 valid element 时，仍然渲染 button
    expect(screen.getByRole('button')).toBeInTheDocument()
  })

  it('disabled 时不可点击并应用 disabled 样式', () => {
    const handleClick = vi.fn()
    render(
      <Button disabled onClick={handleClick}>
        禁用
      </Button>,
    )
    const btn = screen.getByRole('button')
    expect(btn).toBeDisabled()
    expect(btn).toHaveClass('disabled:opacity-50')
    fireEvent.click(btn)
    expect(handleClick).not.toHaveBeenCalled()
  })

  it('普通模式触发 onClick 事件', () => {
    const handleClick = vi.fn()
    render(<Button onClick={handleClick}>触发</Button>)
    fireEvent.click(screen.getByRole('button'))
    expect(handleClick).toHaveBeenCalledTimes(1)
  })

  it('自定义 className 与默认 className 合并', () => {
    render(<Button className="my-custom">自定义</Button>)
    const btn = screen.getByRole('button')
    expect(btn).toHaveClass('my-custom')
    expect(btn).toHaveClass('inline-flex') // 默认 class 仍存在
  })

  it('额外 props（如 type、aria-label）正确透传', () => {
    render(
      <Button type="submit" aria-label="提交按钮">
        提交
      </Button>,
    )
    const btn = screen.getByRole('button')
    expect(btn).toHaveAttribute('type', 'submit')
    expect(btn).toHaveAttribute('aria-label', '提交按钮')
  })

  it('ref 正确转发到 button 元素', () => {
    const ref = createRef<HTMLButtonElement>()
    render(<Button ref={ref}>ref 测试</Button>)
    expect(ref.current).toBeInstanceOf(HTMLButtonElement)
  })

  it('isLoading 时显示加载状态', () => {
    render(<Button isLoading>加载中</Button>)
    const btn = screen.getByRole('button')
    // isLoading 只是透传到 button 元素，不会自动设置 disabled
    expect(btn).toBeInTheDocument()
    expect(btn).toHaveTextContent('加载中')
  })
})

