        {d.kdj && (
          <>
            <span style={{ color: KDJ_COLORS.k }}>K</span>
            <span style={{ textAlign: 'right' }}>{d.kdj.k.toFixed(2)}</span>
            <span style={{ color: KDJ_COLORS.d }}>D</span>
            <span style={{ textAlign: 'right' }}>{d.kdj.d.toFixed(2)}</span>
            <span style={{ color: KDJ_COLORS.j }}>J</span>
            <span style={{ textAlign: 'right' }}>{d.kdj.j.toFixed(2)}</span>
          </>
        )}
        {d.rsi !== undefined && (() => {
          const rsiColor = d.rsi >= 70 ? RSI_COLORS.overbought : d.rsi <= 30 ? RSI_COLORS.oversold : RSI_COLORS.line
          return (
            <>
              <span style={{ color: rsiColor }}>RSI</span>
              <span style={{ textAlign: 'right', fontWeight: 600, color: rsiColor }}>{d.rsi.toFixed(1)}</span>
            </>
          )
        })()}
      </div>
    </div>
  )
})

ChartTooltip.displayName = 'ChartTooltip'

const MultiPaneChart = forwardRef<HTMLDivElement, MultiPaneChartProps>(
  (
    {
      data,
      height = 600,
      upColor,
      downColor,
      markers,
      showToolbar = false,
      showMACD = false,
      showKDJ = false,
      showRSI = false,
      macdParams,
      kdjParams,
      rsiParams,
      period = 'daily',
      adjust = 'qfq',
      onPeriodChange,
      onAdjustChange,
      ...divProps
    },
    ref,
  ) => {
    const containerRef = useRef<HTMLDivElement>(null)
    const mainChartRef = useRef<IChartApi | null>(null)
    const macdChartRef = useRef<IChartApi | null>(null)
    const kdjChartRef = useRef<IChartApi | null>(null)
    const rsiChartRef = useRef<IChartApi | null>(null)

    const mainSeriesRef = useRef<ISeriesApi<'Candlestick'> | null>(null)
    const mainMarkersRef = useRef<ISeriesMarkersPluginApi<Time> | null>(null)
    const maSeriesRefs = useRef<Array<ISeriesApi<'Line'> | null>>([])

    const macdResultRef = useRef<MACDResult | null>(null)
    const kdjResultRef = useRef<KDJResult | null>(null)
    const rsiResultRef = useRef<RSIResult | null>(null)

    const positiveColor = upColor ?? CHART_PALETTE_PRO.upColor
    const negativeColor = downColor ?? CHART_PALETTE_PRO.downColor

    // 使用 ref 存储 tooltip 数据，避免 React 重渲染
    const tooltipRef = useRef<TooltipData | null>(null)
    const tooltipElementRef = useRef<HTMLDivElement | null>(null)

    // 直接操作 DOM 更新 tooltip，不触发 React re-render
    const updateTooltip = useCallback((data: TooltipData | null) => {
      tooltipRef.current = data
      const el = tooltipElementRef.current
      if (!el) return

      if ((data?.visible ?? false) !== true) {
        el.style.display = 'none'
        return
      }

      const d = data!
      el.style.display = 'block'
      // 更新内容
      const timeEl = el.querySelector('[data-tooltip-time]')
      if (timeEl) timeEl.textContent = d.time

      const valuesEl = el.querySelector('[data-tooltip-values]')
      if (valuesEl) {
        valuesEl.innerHTML = buildTooltipValuesHtml(d, positiveColor, negativeColor)
      }
    }, [positiveColor, negativeColor])

    const isDailyPeriod = period === 'daily' || period === 'weekly' || period === 'monthly'

    // 计算各 pane 高度
    const toolbarHeight = showToolbar ? 40 : 0
    const availableHeight = height - toolbarHeight
    const subPaneCount = (showMACD ? 1 : 0) + (showKDJ ? 1 : 0) + (showRSI ? 1 : 0)
    const mainPaneRatio = subPaneCount > 0 ? 0.55 : 1
    const subPaneRatio = subPaneCount > 0 ? (1 - mainPaneRatio) / subPaneCount : 0
    const mainPaneHeight = Math.floor(availableHeight * mainPaneRatio)
    const subPaneHeight = Math.floor(availableHeight * subPaneRatio)

    useEffect(() => {
      if (!containerRef.current) return

      logger.info('[MultiPaneChart] 初始化多窗格图表', {
        showMACD,
        showKDJ,
        dataLength: data.length,
      })

      // ===== 主 K 线图 =====
      const mainPane = createMainChartPane(
        containerRef.current, mainPaneHeight, data, positiveColor, negativeColor,
      )
      const { mainChart, mainSeries } = mainPane
      maSeriesRefs.current = mainPane.maSeriesList

      // ===== MACD 副图 =====
      let macdChart: IChartApi | null = null
      const macdSeriesList: Array<ISeriesApi<'Line' | 'Histogram'> | null> = []

      if (showMACD) {
        logger.info('[MultiPaneChart] 创建 MACD 副图窗格', {
          dataLength: data.length,
          macdParams,
        })

        const macdPane = createMacdChartPane(containerRef.current, subPaneHeight, data, macdParams)
        macdChart = macdPane.macdChart
        macdResultRef.current = macdPane.macdResult
        macdSeriesList.push(...macdPane.macdSeriesList)

        logger.info('[MultiPaneChart] MACD 副图创建完成', {
          difCount: macdPane.macdResult.dif.filter(d => d !== null).length,
          deaCount: macdPane.macdResult.dea.filter(d => d !== null).length,
          histogramCount: macdPane.macdResult.histogram.filter(d => d !== null).length,
        })
      }

      // ===== KDJ 副图 =====
      let kdjChart: IChartApi | null = null
      const kdjSeriesList: Array<ISeriesApi<'Line'> | null> = []

      if (showKDJ) {
        logger.info('[MultiPaneChart] 创建 KDJ 副图窗格', {
          dataLength: data.length,
          kdjParams,
        })

        const kdjPane = createKdjChartPane(containerRef.current, subPaneHeight, data, kdjParams)
        kdjChart = kdjPane.kdjChart
        kdjResultRef.current = kdjPane.kdjResult
        kdjSeriesList.push(...kdjPane.kdjSeriesList)

        logger.info('[MultiPaneChart] KDJ 副图创建完成', {
          kCount: kdjPane.kdjResult.k.filter(d => d !== null).length,
          dCount: kdjPane.kdjResult.d.filter(d => d !== null).length,
          jCount: kdjPane.kdjResult.j.filter(d => d !== null).length,
        })
      }

      // ===== RSI 副图 =====
      let rsiChart: IChartApi | null = null
      const rsiSeriesList: Array<ISeriesApi<'Line'> | null> = []

      if (showRSI) {
        logger.info('[MultiPaneChart] 创建 RSI 副图窗格', {
          dataLength: data.length,
          rsiParams,
        })

        const rsiPane = createRsiChartPane(containerRef.current, subPaneHeight, data, rsiParams)
        rsiChart = rsiPane.rsiChart
        rsiResultRef.current = rsiPane.rsiResult
        rsiSeriesList.push(...rsiPane.rsiSeriesList)

        logger.info('[MultiPaneChart] RSI 副图创建完成', {
          rsiCount: rsiPane.rsiResult.rsi.filter(d => d !== null).length,
          last: rsiPane.rsiResult.rsi.filter(d => d !== null).pop()?.value,
        })
      }

      // ===== 十字光标联动（带节流） =====
      const dataIndex = new Map(data.map((d, i) => [String(d.time), i]))

      const onMainCrosshair = createCrosshairHandler({
        mainSeries,
        data,
        dataIndex,
        showMACD,
        showKDJ,
        showRSI,
        macdResultRef,
        kdjResultRef,
        rsiResultRef,
        macdChart,
        kdjChart,
        rsiChart,
        macdSeriesList,
        kdjSeriesList,
        rsiSeriesList,
        updateTooltip,
      })

      mainChart.subscribeCrosshairMove(onMainCrosshair)

      // ===== TimeScale 同步 =====
      syncTimeScales(mainChart, macdChart, kdjChart, rsiChart)

      mainChart.timeScale().fitContent()
      if (macdChart) macdChart.timeScale().fitContent()
      if (kdjChart) kdjChart.timeScale().fitContent()
      if (rsiChart) rsiChart.timeScale().fitContent()

      // ── 高 DPI 自适应：监听容器尺寸变化 ──
      const resizeObserver = new ResizeObserver((entries) => {
        for (const entry of entries) {
          const { width: w, height: h } = entry.contentRect
          if (w <= 0 || h <= 0) continue
          mainChart.applyOptions({ width: w, height: mainPaneHeight })
          if (macdChart) macdChart.applyOptions({ width: w, height: subPaneHeight })
          if (kdjChart) kdjChart.applyOptions({ width: w, height: subPaneHeight })
          if (rsiChart) rsiChart.applyOptions({ width: w, height: subPaneHeight })
        }
      })
      resizeObserver.observe(containerRef.current)

      mainChartRef.current = mainChart
      mainSeriesRef.current = mainSeries
      macdChartRef.current = macdChart
      kdjChartRef.current = kdjChart
      rsiChartRef.current = rsiChart

      logger.info('[MultiPaneChart] 多窗格图表初始化完成', {
        mainPaneHeight,
        subPaneHeight,
        macdEnabled: showMACD,
        kdjEnabled: showKDJ,
        rsiEnabled: showRSI,
      })

      return () => {
        resizeObserver.disconnect()
        mainChart.remove()
        if (macdChart) macdChart.remove()
        if (kdjChart) kdjChart.remove()
        if (rsiChart) rsiChart.remove()
        mainChartRef.current = null
        mainSeriesRef.current = null
        macdChartRef.current = null
        kdjChartRef.current = null
        rsiChartRef.current = null
        maSeriesRefs.current = []
        macdResultRef.current = null
        kdjResultRef.current = null
        rsiResultRef.current = null
      }
    }, [data, positiveColor, negativeColor, showMACD, showKDJ, showRSI, macdParams, kdjParams, rsiParams])

    // Markers
    useEffect(() => {
      if (!mainSeriesRef.current) return

      if (!markers || markers.length === 0) {
        if (mainMarkersRef.current) {
          mainMarkersRef.current.setMarkers([])
        } else {
          mainMarkersRef.current = createSeriesMarkers(mainSeriesRef.current, [])
        }
        return
      }

      mainMarkersRef.current ??= createSeriesMarkers(mainSeriesRef.current, [])

      const chartMarkers: SeriesMarker<Time>[] = markers.map((m) => ({
        time: m.time,
        position: m.position,
        shape: m.shape,
        color: m.color,
        text: m.text,
        size: m.size,
      }))
      mainMarkersRef.current.setMarkers(chartMarkers)
    }, [markers])

    if (ref) {
      if (typeof ref === 'function') {
        ref(containerRef.current)
      } else {
        ;(ref as { current: HTMLDivElement | null }).current = containerRef.current
      }
    }

    return (
      <div {...divProps}>
        {showToolbar && (
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: '0.75rem',
              padding: '0.5rem 0',
              flexWrap: 'wrap',
            }}
          >
            <div style={{ display: 'flex', gap: '2px', background: CHART_PALETTE_PRO.bgLight, borderRadius: '6px', padding: '2px' }}>
              {PERIOD_OPTIONS.map((opt) => (
                <button
                  key={opt.value}
                  onClick={() => onPeriodChange?.(opt.value)}
                  style={{
                    padding: '4px 10px',
                    fontSize: '0.78rem',
                    fontWeight: 500,
                    border: 'none',
                    borderRadius: '4px',
                    cursor: 'pointer',
                    background: period === opt.value
                      ? 'rgba(255,255,255,0.1)'
                      : 'transparent',
                    color: period === opt.value
                      ? CHART_PALETTE_PRO.contrast
                      : CHART_PALETTE_PRO.axis,
                    transition: 'all 0.15s ease',
                  }}
                >
                  {opt.label}
                </button>
              ))}
            </div>

            {isDailyPeriod && (
              <div style={{ display: 'flex', gap: '2px', background: CHART_PALETTE_PRO.bgLight, borderRadius: '6px', padding: '2px' }}>
                {ADJUST_OPTIONS.map((opt) => (
                  <button
                    key={opt.value || 'none'}
                    onClick={() => onAdjustChange?.(opt.value)}
                    style={{
                      padding: '4px 10px',
                      fontSize: '0.78rem',
                      fontWeight: 500,
                      border: 'none',
                      borderRadius: '4px',
                      cursor: 'pointer',
                      background: adjust === opt.value
                        ? 'rgba(255,255,255,0.1)'
                        : 'transparent',
                      color: adjust === opt.value
                        ? CHART_PALETTE_PRO.contrast
                        : CHART_PALETTE_PRO.axis,
                      transition: 'all 0.15s ease',
                    }}
                  >
                    {opt.label}
                  </button>
                ))}
              </div>
            )}
          </div>
        )}

        <div ref={containerRef} style={{ position: 'relative' }}>
          <div
            ref={tooltipElementRef}
            style={{
              position: 'absolute',
              top: 8,
              right: 8,
              zIndex: 6,
              minWidth: 150,
              padding: '8px 10px',
              borderRadius: '8px',
              background: 'rgba(19,23,34,0.88)',
              backdropFilter: 'blur(6px)',
              border: `1px solid ${CHART_PALETTE_PRO.grid}`,
              boxShadow: '0 4px 16px rgba(0,0,0,0.35)',
              fontSize: '0.74rem',
              fontFeatureSettings: 'tnum',
              color: CHART_PALETTE_PRO.axis,
              pointerEvents: 'none',
              display: 'none',
            }}
          >
            <div data-tooltip-time style={{ fontWeight: 600, marginBottom: 4, color: CHART_PALETTE_PRO.contrast }} />
            <div data-tooltip-values style={{ display: 'grid', gridTemplateColumns: 'auto 1fr', gap: '2px 10px' }} />
          </div>
        </div>
      </div>
    )
  }
)

MultiPaneChart.displayName = 'MultiPaneChart'

const MultiPaneChartMemo = memo(MultiPaneChart)
MultiPaneChartMemo.displayName = 'MultiPaneChart'

export const MultiPaneChartComponent = MultiPaneChartMemo
export { MultiPaneChartComponent as MultiPaneChart }
export type { TooltipData, MultiPaneChartProps } from './multiPaneChart.types'

export default MultiPaneChartMemo

/**
 * 画线工具渲染引擎
 *
 * 使用 lightweight-charts 的 IPrimitive 接口渲染：
 * - 趋势线：两点连线，支持双向延伸
 * - 水平线：指定价格的水平虚线
 * - 射线：从起点沿角度延伸
 *
 * 支持：
 * - 实时绘制（鼠标拖拽）
 * - 选中态高亮（金色）
 * - 标签显示
 * - 吸附到 OHLC 极值
 *
 * 对标 TradingView 画线工具交互体验。
 *
 * @module components/chart/drawing/engine
 * @created 2026-08-15
 */

import type {
  IChartApi,
  ISeriesApi,
  Time,
  CandlestickData,
} from 'lightweight-charts'
import {
  LINE_STYLE_MAP,
  generateDrawingId,
  type Drawing,
  type TrendLine,
  type HorizontalLine,
  type RayLine,
  type DrawingToolType,
  type DrawingManagerState,
  type DrawingToolConfig,
  DEFAULT_DRAWING_CONFIG,
} from './types'
import { getLogger } from '@/lib/logger'

const logger = getLogger()

/** 画线工具管理器 */
export class DrawingManager {
  private chart: IChartApi
  private series: ISeriesApi<'Candlestick'>
  private config: DrawingToolConfig
  private state: DrawingManagerState = {
    drawings: [],
    activeTool: null,
    pendingDrawing: null,
    visible: true,
  }

  /** 当前拖拽中的起点 */
  private dragStart: { time: Time; price: number } | null = null

  /** 事件解绑函数 */
  private unbindClick: (() => void) | null = null
  private unbindMove: (() => void) | null = null

  constructor(
    chart: IChartApi,
    series: ISeriesApi<'Candlestick'>,
    config: Partial<DrawingToolConfig> = {},
  ) {
    this.chart = chart
    this.series = series
    this.config = { ...DEFAULT_DRAWING_CONFIG, ...config }
  }

  /** 获取当前状态 */
  getState(): Readonly<DrawingManagerState> {
    return this.state
  }

  /** 获取所有画线 */
  getDrawings(): readonly Drawing[] {
    return this.state.drawings
  }

  /** 激活画线工具 */
  activateTool(tool: DrawingToolType): void {
    this.deactivateTool()
    this.state.activeTool = tool
    this.bindEvents()
    logger.info('[Drawing] 激活画线工具', { tool })
  }

  /** 停用画线工具 */
  deactivateTool(): void {
    this.state.activeTool = null
    this.state.pendingDrawing = null
    this.dragStart = null
    this.unbindAll()
    logger.info('[Drawing] 停用画线工具')
  }

  /** 添加画线 */
  addDrawing(drawing: Drawing): void {
    this.state.drawings.push(drawing)
    this.renderDrawings()
    logger.info('[Drawing] 添加画线', { id: drawing.id, type: drawing.type })
  }

  /** 删除画线 */
  removeDrawing(id: string): void {
    const idx = this.state.drawings.findIndex(d => d.id === id)
    if (idx >= 0) {
      this.state.drawings.splice(idx, 1)
      this.renderDrawings()
      logger.info('[Drawing] 删除画线', { id })
    }
  }

  /** 清除所有画线 */
  clearAll(): void {
    this.state.drawings = []
    this.renderDrawings()
    logger.info('[Drawing] 清除所有画线')
  }

  /** 设置可见性 */
  setVisible(visible: boolean): void {
    this.state.visible = visible
    this.renderDrawings()
  }

  /** 渲染所有画线到图表 */
  private renderDrawings(): void {
    // 移除所有现有画线 primitive
    this.chart.removeAllSeries()

    if (!this.state.visible || this.state.drawings.length === 0) {
      return
    }

    // 重新添加 series
    this.series = this.chart.addCandlestickSeries()

    for (const drawing of this.state.drawings) {
      this.renderDrawing(drawing)
    }
  }

  /** 渲染单条画线 */
  private renderDrawing(drawing: Drawing): void {
    switch (drawing.type) {
      case 'trendLine':
        this.renderTrendLine(drawing)
        break
      case 'horizontalLine':
        this.renderHorizontalLine(drawing)
        break
      case 'rayLine':
        this.renderRayLine(drawing)
        break
    }
  }

  /** 渲染趋势线 */
  private renderTrendLine(line: TrendLine): void {
    // 使用 LineSeries 渲染趋势线
    const lineSeries = this.chart.addLineSeries({
      color: line.color,
      lineWidth: line.lineWidth,
      lineStyle: LINE_STYLE_MAP[line.lineStyle],
      priceLineVisible: false,
      lastValueVisible: false,
      crosshairMarkerVisible: false,
    })

    // 计算线上所有点
    const points = this.calculateTrendLinePoints(line)
    lineSeries.setData(points)
  }

  /** 计算趋势线上的点 */
  private calculateTrendLinePoints(
    line: TrendLine,
  ): Array<{ time: Time; value: number }> {
    const t1 = typeof line.point1.time === 'number'
      ? line.point1.time
      : new Date(line.point1.time as string).getTime() / 1000
    const t2 = typeof line.point2.time === 'number'
      ? line.point2.time
      : new Date(line.point2.time as string).getTime() / 1000

    const priceDiff = line.point2.price - line.point1.price
    const timeDiff = t2 - t1

    if (timeDiff === 0) {
      return [line.point1, line.point2].map(p => ({
        time: p.time,
        value: p.price,
      }))
    }

    const slope = priceDiff / timeDiff
    const points: Array<{ time: Time; value: number }> = []

    // 起点
    points.push({ time: line.point1.time, value: line.point1.price })

    // 终点
    points.push({ time: line.point2.time, value: line.point2.price })

    // 向左延伸
    if (line.extendLeft) {
      const extTime = t1 - timeDiff * 0.5
      const extPrice = line.point1.price - slope * timeDiff * 0.5
      points.unshift({
        time: Math.floor(extTime) as Time,
        value: Number(extPrice.toFixed(3)),
      })
    }

    // 向右延伸
    if (line.extendRight) {
      const extTime = t2 + timeDiff * 0.5
      const extPrice = line.point2.price + slope * timeDiff * 0.5
      points.push({
        time: Math.floor(extTime) as Time,
        value: Number(extPrice.toFixed(3)),
      })
    }

    return points
  }

  /** 渲染水平线 */
  private renderHorizontalLine(line: HorizontalLine): void {
    const lineSeries = this.chart.addLineSeries({
      color: line.color,
      lineWidth: line.lineWidth,
      lineStyle: LINE_STYLE_MAP[line.lineStyle],
      priceLineVisible: false,
      lastValueVisible: false,
      crosshairMarkerVisible: false,
    })

    // 获取图表时间范围
    const timeScale = this.chart.timeScale()
    const visibleRange = timeScale.getVisibleRange()

    const data: Array<{ time: Time; value: number }> = []
    if (line.startTime && line.endTime) {
      data.push(
        { time: line.startTime, value: line.price },
        { time: line.endTime, value: line.price },
      )
    } else if (visibleRange) {
      data.push(
        { time: visibleRange.from as Time, value: line.price },
        { time: visibleRange.to as Time, value: line.price },
      )
    }

    if (data.length > 0) {
      lineSeries.setData(data)
    }
  }

  /** 渲染射线 */
  private renderRayLine(line: RayLine): void {
    const lineSeries = this.chart.addLineSeries({
      color: line.color,
      lineWidth: line.lineWidth,
      lineStyle: LINE_STYLE_MAP[line.lineStyle],
      priceLineVisible: false,
      lastValueVisible: false,
      crosshairMarkerVisible: false,
    })

    const t0 = typeof line.point.time === 'number'
      ? line.point.time
      : new Date(line.point.time as string).getTime() / 1000

    const timeScale = this.chart.timeScale()
    const visibleRange = timeScale.getVisibleRange()
    const endTime = visibleRange?.to ?? (t0 + 86400 * 30)

    const tEnd = typeof endTime === 'number' ? endTime : 0
    const priceEnd = line.point.price + Math.tan(line.angle) * (tEnd - t0) / 86400

    lineSeries.setData([
      { time: line.point.time, value: line.point.price },
      { time: endTime, value: Number(priceEnd.toFixed(3)) },
    ])
  }

  /** 绑定鼠标事件 */
  private bindEvents(): void {
    this.unbindAll()

    this.unbindClick = this.chart.subscribeClick((param) => {
      if (!this.state.activeTool) return
      if (!param.point || !param.time) return

      const price = this.getPriceAtTime(param.time)
      if (price == null) return

      this.handleClick(param.time, price)
    })

    this.unbindMove = this.chart.subscribeCrosshairMove((param) => {
      if (!this.state.activeTool || !this.dragStart) return
      if (!param.point || !param.time) return

      const price = this.getPriceAtTime(param.time)
      if (price == null) return

      this.handleDragMove(param.time, price)
    })
  }

  /** 处理点击 */
  private handleClick(time: Time, price: number): void {
    const tool = this.state.activeTool!

    if (tool === 'horizontalLine') {
      const line: HorizontalLine = {
        id: generateDrawingId(),
        type: 'horizontalLine',
        color: this.config.defaultColor,
        lineWidth: this.config.defaultLineWidth,
        lineStyle: this.config.defaultLineStyle,
        showLabel: true,
        label: price.toFixed(2),
        extend: false,
        opacity: this.config.defaultOpacity,
        createdAt: Date.now(),
        price,
      }
      this.addDrawing(line)
      return
    }

    if (tool === 'trendLine') {
      if (!this.dragStart) {
        // 第一次点击：设置起点
        this.dragStart = { time, price }
      } else {
        // 第二次点击：完成趋势线
        const line: TrendLine = {
          id: generateDrawingId(),
          type: 'trendLine',
          color: this.config.defaultColor,
          lineWidth: this.config.defaultLineWidth,
          lineStyle: this.config.defaultLineStyle,
          showLabel: true,
          extend: true,
          extendRight: true,
          extendLeft: false,
          opacity: this.config.defaultOpacity,
          createdAt: Date.now(),
          point1: this.dragStart,
          point2: { time, price },
        }
        this.addDrawing(line)
        this.dragStart = null
      }
    }
  }

  /** 处理拖拽移动 */
  private handleDragMove(_time: Time, _price: number): void {
    // 拖拽中预览（可选实现）
  }

  /** 根据时间获取价格 */
  private getPriceAtTime(time: Time): number | null {
    try {
      const seriesData = this.series.data() as CandlestickData<Time>[]
      const item = seriesData.find(d => {
        if (typeof d.time === 'number' && typeof time === 'number') {
          return d.time === time
        }
        return String(d.time) === String(time)
      })
      if (item) {
        return item.close
      }
    } catch {
      // 忽略
    }
    return null
  }

  /** 解绑所有事件 */
  private unbindAll(): void {
    if (this.unbindClick) {
      this.unbindClick()
      this.unbindClick = null
    }
    if (this.unbindMove) {
      this.unbindMove()
      this.unbindMove = null
    }
  }

  /** 销毁 */
  destroy(): void {
    this.deactivateTool()
    this.clearAll()
  }
}

/**
 * 图表缩放控制 Hook
 *
 * 提供：
 * - 复位缩放（双击或按钮）
 * - 缩放级别显示
 * - 键盘快捷键（←→ 平移，+/- 缩放，R 复位）
 * - 自适应降采样触发
 *
 * 对标 TradingView 缩放交互体验。
 *
 * @module components/chart/hooks/useChartZoom
 * @created 2026-08-15
 */

import { useEffect, useCallback, useRef, useState } from 'react'
import type { IChartApi } from 'lightweight-charts'
import { getLogger } from '@/lib/logger'

const logger = getLogger()

/** 缩放控制 Hook 参数 */
export interface UseChartZoomOptions {
  /** 图表实例 */
  chart: IChartApi | null
  /** 是否启用键盘快捷键 */
  enableKeyboard?: boolean
  /** 是否启用双击复位 */
  enableDoubleClickReset?: boolean
  /** 自适应降采样回调 */
  onVisibleRangeChange?: (visibleBars: number) => void
}

/** 缩放控制 Hook 返回值 */
export interface UseChartZoomReturn {
  /** 可见 K 线数量 */
  visibleBars: number
  /** 缩放级别 (0-100) */
  zoomLevel: number
  /** 是否已缩放到最大 */
  isMaxZoomed: boolean
  /** 是否已缩放到最小（全览） */
  isMinZoomed: boolean
  /** 复位缩放 */
  resetZoom: () => void
  /** 缩放到指定范围 */
  zoomToRange: (from: number, to: number) => void
  /** 缩放步进 */
  zoomIn: () => void
  zoomOut: () => void
  /** 平移 */
  panLeft: () => void
  panRight: () => void
}

/**
 * 图表缩放控制 Hook
 */
export function useChartZoom(options: UseChartZoomOptions): UseChartZoomReturn {
  const {
    chart,
    enableKeyboard = true,
    enableDoubleClickReset = true,
    onVisibleRangeChange,
  } = options

  const [visibleBars, setVisibleBars] = useState(0)
  const [zoomLevel, setZoomLevel] = useState(50)
  const [isMaxZoomed, setIsMaxZoomed] = useState(false)
  const [isMinZoomed, setIsMinZoomed] = useState(false)
  const totalBarsRef = useRef(0)

  // 监听可视范围变化
  useEffect(() => {
    if (!chart) return

    const timeScale = chart.timeScale()

    const updateVisibleRange = () => {
      const range = timeScale.getVisibleRange()
      if (!range) return

      const from = typeof range.from === 'number' ? range.from : 0
      const to = typeof range.to === 'number' ? range.to : 0
      const bars = timeScale.options().barSpacing
        ? Math.floor((to - from) / (86400 / bars)) // 近似估算
        : 0

      setVisibleBars(bars)

      // 计算缩放级别
      if (totalBarsRef.current > 0) {
        const level = Math.min(
          100,
          Math.max(0, Math.round((bars / totalBarsRef.current) * 100)),
        )
        setZoomLevel(level)
        setIsMaxZoomed(bars <= 5)
        setIsMinZoomed(level >= 95)
      }

      if (onVisibleRangeChange) {
        onVisibleRangeChange(bars)
      }
    }

    const unsubscribe = timeScale.subscribeVisibleLogicalRangeChange(() => {
      updateVisibleRange()
    })

    updateVisibleRange()

    return () => {
      unsubscribe()
    }
  }, [chart, onVisibleRangeChange])

  // 设置总 K 线数
  useEffect(() => {
    if (!chart) return
    const series = chart.series()[0]
    if (series) {
      const data = series.data()
      totalBarsRef.current = data.length
    }
  }, [chart])

  // 复位缩放
  const resetZoom = useCallback(() => {
    if (!chart) return
    chart.timeScale().fitContent()
    logger.info('[Zoom] 复位缩放')
  }, [chart])

  // 缩放到指定范围
  const zoomToRange = useCallback((from: number, to: number) => {
    if (!chart) return
    chart.timeScale().setVisibleRange({ from: from as any, to: to as any })
  }, [chart])

  // 缩放步进
  const zoomIn = useCallback(() => {
    if (!chart) return
    const timeScale = chart.timeScale()
    const range = timeScale.getVisibleRange()
    if (!range) return
    const from = typeof range.from === 'number' ? range.from : 0
    const to = typeof range.to === 'number' ? range.to : 0
    const mid = (from + to) / 2
    const half = (to - from) * 0.35
    timeScale.setVisibleRange({
      from: (mid - half) as any,
      to: (mid + half) as any,
    })
  }, [chart])

  const zoomOut = useCallback(() => {
    if (!chart) return
    const timeScale = chart.timeScale()
    const range = timeScale.getVisibleRange()
    if (!range) return
    const from = typeof range.from === 'number' ? range.from : 0
    const to = typeof range.to === 'number' ? range.to : 0
    const mid = (from + to) / 2
    const half = (to - from) * 0.7
    timeScale.setVisibleRange({
      from: (mid - half) as any,
      to: (mid + half) as any,
    })
  }, [chart])

  // 平移
  const panLeft = useCallback(() => {
    if (!chart) return
    const timeScale = chart.timeScale()
    const range = timeScale.getVisibleRange()
    if (!range) return
    const shift = (typeof range.to === 'number' ? range.to : 0) -
      (typeof range.from === 'number' ? range.from : 0)
    const newFrom = (typeof range.from === 'number' ? range.from : 0) - shift * 0.3
    const newTo = (typeof range.to === 'number' ? range.to : 0) - shift * 0.3
    timeScale.setVisibleRange({ from: newFrom as any, to: newTo as any })
  }, [chart])

  const panRight = useCallback(() => {
    if (!chart) return
    const timeScale = chart.timeScale()
    const range = timeScale.getVisibleRange()
    if (!range) return
    const shift = (typeof range.to === 'number' ? range.to : 0) -
      (typeof range.from === 'number' ? range.from : 0)
    const newFrom = (typeof range.from === 'number' ? range.from : 0) + shift * 0.3
    const newTo = (typeof range.to === 'number' ? range.to : 0) + shift * 0.3
    timeScale.setVisibleRange({ from: newFrom as any, to: newTo as any })
  }, [chart])

  // 键盘快捷键
  useEffect(() => {
    if (!enableKeyboard || !chart) return

    const handleKeyDown = (e: KeyboardEvent) => {
      // 不在输入框中时响应
      if (
        e.target instanceof HTMLInputElement ||
        e.target instanceof HTMLTextAreaElement
      ) {
        return
      }

      switch (e.key) {
        case 'ArrowLeft':
          e.preventDefault()
          panLeft()
          break
        case 'ArrowRight':
          e.preventDefault()
          panRight()
          break
        case '+':
        case '=':
          e.preventDefault()
          zoomIn()
          break
        case '-':
          e.preventDefault()
          zoomOut()
          break
        case 'r':
        case 'R':
          if (!e.ctrlKey && !e.metaKey) {
            e.preventDefault()
            resetZoom()
          }
          break
      }
    }

    window.addEventListener('keydown', handleKeyDown)
    return () => {
      window.removeEventListener('keydown', handleKeyDown)
    }
  }, [enableKeyboard, chart, resetZoom, zoomIn, zoomOut, panLeft, panRight])

  // 双击复位
  useEffect(() => {
    if (!enableDoubleClickReset || !chart) return

    const handleDblClick = () => {
      resetZoom()
    }

    const chartEl = (chart as any)._chartElement as HTMLElement | undefined
    if (chartEl) {
      chartEl.addEventListener('dblclick', handleDblClick)
      return () => {
        chartEl.removeEventListener('dblclick', handleDblClick)
      }
    }
  }, [enableDoubleClickReset, chart, resetZoom])

  return {
    visibleBars,
    zoomLevel,
    isMaxZoomed,
    isMinZoomed,
    resetZoom,
    zoomToRange,
    zoomIn,
    zoomOut,
    panLeft,
    panRight,
  }
}

/**
 * @fileoverview P2 签名视觉锚点：信号强度谱（SignalSpectrum）
 *
 * 全局统一的「信号强度」母题，将 0-100 的评分/信号强度映射为
 * 弱(琥珀) → 中(蓝) → 强(翠绿) 的连续谱，并标注当前位置。
 * 纯展示组件，全部引用令牌，无硬编码颜色。
 *
 * @module components/cockpit/SignalSpectrum
 */
import { type HTMLAttributes } from 'react'
import { cn } from '@/lib/utils'
import { THEME_TOKENS, COLOR_TOKENS } from '@/constants/theme.tokens'

export interface SignalSpectrumProps extends HTMLAttributes<HTMLDivElement> {
  /** 信号强度 0-100 */
  value: number
  /** 标签文案 */
  label?: string
  /** 是否显示数值 */
  showValue?: boolean
  /** 尺寸 */
  size?: 'sm' | 'md' | 'lg'
}

const SIZE_MAP = {
  sm: { track: 'h-1.5', text: THEME_TOKENS.typography.fontSize.xs },
  md: { track: 'h-2.5', text: THEME_TOKENS.typography.fontSize.sm },
  lg: { track: 'h-3.5', text: THEME_TOKENS.typography.fontSize.base },
} as const

/**
 * SignalSpectrum
 */
export function SignalSpectrum({
  value,
  label,
  showValue = true,
  size = 'md',
  className,
  ...props
}: SignalSpectrumProps) {
  const clamped = Math.max(0, Math.min(100, value))
  const gradient = `linear-gradient(to right, ${COLOR_TOKENS.warning.hex} 0%, ${COLOR_TOKENS.info.hex} 50%, ${COLOR_TOKENS.emerald.hex} 100%)`

  return (
    <div className={cn('flex w-full flex-col', THEME_TOKENS.gap.xs, className)} {...props}>
      {(label ?? showValue) && (
        <div
          className={cn(
            'flex items-center justify-between',
            SIZE_MAP[size].text,
            THEME_TOKENS.typography.fontWeight.medium,
          )}
        >
          {label && <span className={COLOR_TOKENS.textMuted.tailwind}>{label}</span>}
          {showValue && (
            <span className={COLOR_TOKENS.emerald.tailwind}>{Math.round(clamped)}</span>
          )}
        </div>
      )}
      <div
        className={cn(
          'relative w-full',
          THEME_TOKENS.radius.full,
          THEME_TOKENS.color.mutedBackground,
          SIZE_MAP[size].track,
        )}
      >
        <div
          className={cn('absolute inset-y-0 left-0', THEME_TOKENS.radius.full)}
          style={{ width: `${clamped}%`, background: gradient }}
        />
        <div
          className={cn(
            'absolute top-1/2 -translate-x-1/2 -translate-y-1/2 border-2 border-white shadow',
            THEME_TOKENS.radius.full,
            SIZE_MAP[size].track,
          )}
          style={{ left: `${clamped}%`, background: COLOR_TOKENS.emerald.hex }}
        />
      </div>
    </div>
  )
}

export default SignalSpectrum

/**
 * 资金管理双轨面板
 *
 * 展示 30% 耐心资本 / 70% 博收益的双轨配置可视化，
 * 包括分仓比例、KPI 考核指标、大跌应对纪律。
 *
 * 设计哲学：资金如兵力——不能平均分散，集中优势兵力在核心赛道。
 *
 * @doc 资金管理与交易纪律框架（见 docs/specs/02-functional-specs.md §2.4.18）
 */

import { memo } from 'react'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/atoms/Card'
import { DEFAULT_CAPITAL_ALLOCATION_CONFIG, type CapitalAllocationConfig } from '@/config/capitalAllocationConfig'
import { COLOR_TOKENS } from '@/constants/theme.tokens'

export interface CapitalAllocationPanelProps {
  /** 资金配置，默认使用 DEFAULT_CAPITAL_ALLOCATION_CONFIG */
  config?: CapitalAllocationConfig
  /** 耐心资本当前实际占比（0-1），用于对比目标 */
  patientCapitalActualPct?: number
  /** 博收益当前实际占比（0-1） */
  betaYieldActualPct?: number
  /** KPI 指标当前值（可选，不传则只展示目标线） */
  kpiActual?: {
    annualReturn?: number
    quarterlyReturn?: number
    monthlyWinRate?: number
    disciplineRate?: number
  }
  className?: string
}

/** 格式化百分比 */
function fmtPct(value: number, digits = 1): string {
  return `${(value * 100).toFixed(digits)}%`
}

/** 格式化带符号百分比 */
function fmtSignedPct(value: number, digits = 1): string {
  const sign = value >= 0 ? '+' : ''
  return `${sign}${(value * 100).toFixed(digits)}%`
}

/** KPI 达标状态 */
function getKpiStatus(actual: number | undefined, min: number, excellent: number): {
  status: 'none' | 'fail' | 'pass' | 'excellent'
  label: string
} {
  if (actual === undefined) return { status: 'none', label: '—' }
  if (actual >= excellent) return { status: 'excellent', label: '优秀' }
  if (actual >= min) return { status: 'pass', label: '合格' }
  return { status: 'fail', label: '未达标' }
}

const STATUS_COLOR: Record<string, string> = {
  none: 'text-muted-foreground',
  fail: COLOR_TOKENS.danger.tailwind,
  pass: COLOR_TOKENS.success.tailwind,
  excellent: COLOR_TOKENS.scoreHigh?.tailwind ?? COLOR_TOKENS.success.tailwind,
}

/**
 * 资金管理双轨面板
 */
export const CapitalAllocationPanel = memo(function CapitalAllocationPanel({
  config = DEFAULT_CAPITAL_ALLOCATION_CONFIG,
  patientCapitalActualPct,
  betaYieldActualPct,
  kpiActual,
  className,
}: CapitalAllocationPanelProps) {
  const { betaYieldKpi: kpi, drawdownDiscipline: dd } = config

  // KPI 达标状态计算
  const annualStatus = getKpiStatus(kpiActual?.annualReturn, kpi.annualReturnMin, kpi.annualReturnExcellent)
  const quarterlyStatus = getKpiStatus(kpiActual?.quarterlyReturn, kpi.quarterlyReturnMin, kpi.quarterlyReturnExcellent)
  const winRateStatus = getKpiStatus(kpiActual?.monthlyWinRate, kpi.monthlyWinRateMin, kpi.monthlyWinRateExcellent)
  const disciplineStatus = getKpiStatus(kpiActual?.disciplineRate, kpi.disciplineRateMin, kpi.disciplineRateExcellent)

  return (
    <Card className={className}>
      <CardHeader>
        <CardTitle>资金管理双轨配置</CardTitle>
        <p className="text-xs text-muted-foreground mt-1">
          资金如兵力——集中优势兵力在核心赛道，30% 铆住 + 70% 博收益
        </p>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* 分仓比例可视化 */}
        <div className="space-y-2">
          <div className="text-sm font-medium">分仓比例</div>
          <div className="flex h-8 w-full overflow-hidden rounded-md">
            <div
              className="flex items-center justify-center text-xs font-medium text-white"
              style={{
                width: `${config.patientCapitalPct * 100}%`,
                backgroundColor: getColorHexSafe('scoreHigh'),
              }}
            >
              耐心资本 {fmtPct(config.patientCapitalPct, 0)}
            </div>
            <div
              className="flex items-center justify-center text-xs font-medium text-white"
              style={{
                width: `${config.betaYieldPct * 100}%`,
                backgroundColor: getColorHexSafe('primary'),
              }}
            >
              博收益 {fmtPct(config.betaYieldPct, 0)}
            </div>
          </div>
          {/* 实际占比对比 */}
          {(patientCapitalActualPct !== undefined || betaYieldActualPct !== undefined) && (
            <div className="flex h-4 w-full overflow-hidden rounded-sm opacity-60">
              <div
                className="flex items-center justify-center text-[10px]"
                style={{ width: `${(patientCapitalActualPct ?? 0) * 100}%` }}
              >
                实际 {fmtPct(patientCapitalActualPct ?? 0, 0)}
              </div>
              <div
                className="flex items-center justify-center text-[10px]"
                style={{ width: `${(betaYieldActualPct ?? 0) * 100}%` }}
              >
                实际 {fmtPct(betaYieldActualPct ?? 0, 0)}
              </div>
            </div>
          )}
        </div>

        {/* 耐心资本信息 */}
        <div className="rounded-md border p-3 space-y-1">
          <div className="text-sm font-medium" style={{ color: getColorHexSafe('scoreHigh') }}>
            耐心资本（铆住不卖）
          </div>
          <div className="grid grid-cols-2 gap-1 text-xs text-muted-foreground">
            <span>投资周期：{config.patientCapitalHorizonYears} 年</span>
            <span>目标收益：{(config.patientCapitalTargetReturnMin - 1) * 100}%-{(config.patientCapitalTargetReturnMax - 1) * 100}%</span>
            <span className="col-span-2">纪律：逢大跌加仓，不止损，2-3 年为周期持有</span>
          </div>
        </div>

        {/* 博收益 KPI 考核 */}
        <div className="rounded-md border p-3 space-y-2">
          <div className="text-sm font-medium" style={{ color: getColorHexSafe('primary') }}>
            博收益 KPI 考核
          </div>
          <div className="grid grid-cols-2 gap-2 text-xs">
            <KpiRow
              label="年化收益率"
              target={`≥ ${fmtPct(kpi.annualReturnMin)} / ${fmtPct(kpi.annualReturnExcellent)}`}
              actual={kpiActual?.annualReturn !== undefined ? fmtSignedPct(kpiActual.annualReturn) : undefined}
              status={annualStatus}
            />
            <KpiRow
              label="季度收益率"
              target={`≥ ${fmtPct(kpi.quarterlyReturnMin)} / ${fmtPct(kpi.quarterlyReturnExcellent)}`}
              actual={kpiActual?.quarterlyReturn !== undefined ? fmtSignedPct(kpiActual.quarterlyReturn) : undefined}
              status={quarterlyStatus}
            />
            <KpiRow
              label="月度胜率"
              target={`≥ ${fmtPct(kpi.monthlyWinRateMin)} / ${fmtPct(kpi.monthlyWinRateExcellent)}`}
              actual={kpiActual?.monthlyWinRate !== undefined ? fmtPct(kpiActual.monthlyWinRate) : undefined}
              status={winRateStatus}
            />
            <KpiRow
              label="纪律执行率"
              target={`≥ ${fmtPct(kpi.disciplineRateMin)} / ${fmtPct(kpi.disciplineRateExcellent)}`}
              actual={kpiActual?.disciplineRate !== undefined ? fmtPct(kpiActual.disciplineRate) : undefined}
              status={disciplineStatus}
            />
            <div className="col-span-2 flex gap-4 text-muted-foreground">
              <span>单笔止盈：+{fmtPct(kpi.singleTakeProfit, 0)}</span>
              <span>单笔止损：{fmtPct(kpi.singleStopLoss, 0)}</span>
            </div>
          </div>
        </div>

        {/* 大跌应对纪律 */}
        <div className="rounded-md border p-3 space-y-2">
          <div className="text-sm font-medium">大跌应对纪律</div>
          <div className="space-y-1 text-xs">
            <DrawdownRow
              label="个股小跌"
              range={`>${fmtPct(dd.individualMildDrawdown, 0)}`}
              patientAction="继续持有"
              betaAction="止损卖出"
            />
            <DrawdownRow
              label="个股中跌"
              range={`${fmtPct(dd.individualModerateDrawdown, 0)} ~ ${fmtPct(dd.individualMildDrawdown, 0)}`}
              patientAction="分批加仓"
              betaAction="已离场观望"
            />
            <DrawdownRow
              label="个股大跌"
              range={`<${fmtPct(dd.individualSevereDrawdown, 0)}`}
              patientAction="继续加仓，铆住不卖"
              betaAction="等待企稳"
            />
            <DrawdownRow
              label="大盘大跌"
              range={`>${fmtPct(dd.marketSystemicDrawdown, 0)}`}
              patientAction="加仓核心稀缺"
              betaAction={`降仓至 ${fmtPct(dd.betaYieldReducePositionTo, 0)}`}
            />
            <DrawdownRow
              label="大盘暴跌"
              range={`>${fmtPct(dd.marketCrashDrawdown, 0)}`}
              patientAction="满仓核心稀缺"
              betaAction="清仓防守"
            />
          </div>
        </div>
      </CardContent>
    </Card>
  )
})

/** KPI 行 */
function KpiRow({
  label,
  target,
  actual,
  status,
}: {
  label: string
  target: string
  actual?: string
  status: { status: string; label: string }
}) {
  return (
    <div className="flex flex-col gap-0.5">
      <div className="flex items-center justify-between">
        <span className="text-muted-foreground">{label}</span>
        <span className={`font-medium ${STATUS_COLOR[status.status] ?? ''}`}>
          {actual ?? '—'} {status.label !== '—' && `(${status.label})`}
        </span>
      </div>
      <span className="text-[10px] text-muted-foreground">目标：{target}</span>
    </div>
  )
}

/** 大跌应对行 */
function DrawdownRow({
  label,
  range,
  patientAction,
  betaAction,
}: {
  label: string
  range: string
  patientAction: string
  betaAction: string
}) {
  return (
    <div className="grid grid-cols-[80px_80px_1fr_1fr] items-center gap-1">
      <span className="font-medium">{label}</span>
      <span className="text-muted-foreground">{range}</span>
      <span>
        <span className="text-muted-foreground">耐心：</span>
        <span style={{ color: getColorHexSafe('scoreHigh') }}>{patientAction}</span>
      </span>
      <span>
        <span className="text-muted-foreground">博收益：</span>
        <span style={{ color: getColorHexSafe('danger') }}>{betaAction}</span>
      </span>
    </div>
  )
}

/** 安全获取颜色 hex（避免 undefined 报错） */
function getColorHexSafe(key: string): string {
  const token = (COLOR_TOKENS as Record<string, { hex?: string }>)[key]
  return token?.hex ?? '#6366f1'
}

import { type ButtonHTMLAttributes, type DialogHTMLAttributes, forwardRef, useEffect, useRef } from 'react'
import { cn } from '@/lib/utils'
import { X } from 'lucide-react'

export interface DialogProps extends DialogHTMLAttributes<HTMLDialogElement> {
  open?: boolean
  onOpenChange?: (open: boolean) => void
}

/**
 * Dialog
 */
export const Dialog = forwardRef<HTMLDialogElement, DialogProps>(
  ({ className, open, onOpenChange, children, ...props }, ref) => {
    const internalRef = useRef<HTMLDialogElement>(null)
    const dialogRef = (ref as React.RefObject<HTMLDialogElement>) || internalRef

    useEffect(() => {
      const dialog = dialogRef.current
      if (!dialog) return
      if (open && !dialog.open) {
        dialog.showModal()
      } else if (!open && dialog.open) {
        dialog.close()
      }
    }, [open, dialogRef])

    useEffect(() => {
      const dialog = dialogRef.current
      if (!dialog) return
      const handleClose = () => onOpenChange?.(false)
      dialog.addEventListener('close', handleClose)
      return () => dialog.removeEventListener('close', handleClose)
    }, [onOpenChange, dialogRef])

    return (
      <dialog
        ref={dialogRef}
        className={cn(
          'fixed left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2',
          'm-0 max-h-[85vh] w-full max-w-lg rounded-lg border bg-background p-0 shadow-lg backdrop:bg-black/50',
          'open:animate-in open:fade-in-0 open:zoom-in-95',
          className,
        )}
        {...props}
      >
        {children}
      </dialog>
    )
  },
)
Dialog.displayName = 'Dialog'

