import { cn } from '@/lib/utils'
import { Card, CardContent } from '@/components/atoms'
import { COLOR_TOKENS, type ColorTokenKey, getColorHex } from '@/constants/theme.tokens'
import { getLogger } from '@/lib/logger'

const logger = getLogger()

/** ColorTokenKey 字面量集合（运行时集合，与类型 ColorTokenKey 保持同构） */
const TOKEN_KEY_SET = new Set<ColorTokenKey>(Object.keys(COLOR_TOKENS) as ColorTokenKey[])

export interface MetricCardProps {
  /** 指标标题 */
  title: string
  /** 指标数值 */
  value: string | number
  /** 单位 */
  unit?: string
  /** 趋势方向 */
  trend?: 'up' | 'down' | 'neutral'
  /** 变化文本 */
  change?: string
  /** 是否加载中 */
  loading?: boolean
  /**
   * 强调色
   * - 推荐传入 `ColorTokenKey`（如 `'success'`、`'danger'`、`'scoreHigh'`），自动对齐主题色与深色模式
   * - 兼容直接传 HEX 字符串（`#ef4444`），但会在开发环境触发一次告警，请尽快迁移到 Token 键
   * @example
   * <MetricCard title="智能评分" value={92} color="scoreHigh" border />
   */
  color?: ColorTokenKey | (string & {})
  /** 是否以左边框强调（需配合 color） */
  border?: boolean
  /** 容器 className */
  className?: string
}

/**
 * 解析 MetricCard.color 参数，统一返回 HEX 颜色值
 * - ColorTokenKey → 通过 getColorHex 取主题色（自动兼容红涨绿跌 + 深色模式）
 * - HEX 字符串 → 原样返回（记录一次 warn 提醒迁移）
 * - undefined / null → undefined（走默认渲染）
 */
function resolveColorToken(raw: string | undefined): string | undefined {
  if (raw === undefined || raw === null || raw === '') return undefined
  if (typeof raw === 'string' && TOKEN_KEY_SET.has(raw as ColorTokenKey)) {
    return getColorHex(raw as ColorTokenKey)
  }
  // 向后兼容：HEX 字面量，但打一次日志提醒迁移（避免 UI 层硬编码扩散）
  logger.warn('[MetricCard] color 参数使用了字面量 HEX，请迁移到 ColorTokenKey 键以对齐主题令牌与深色模式', {
    raw,
    suggestion: '例如：将 color="HEX绿" 改为 color="emerald"',
  })
  return raw
}

/**
 * 指标卡分子
 *
 * 组合：Card + 标题 + 数值 + 趋势变化
 */
export function MetricCard({
  title,
  value,
  unit,
  trend = 'neutral',
  change,
  loading,
  color,
  border = false,
  className,
}: MetricCardProps) {
  const trendColor =
    trend === 'up'
      ? COLOR_TOKENS.success.tailwind
      : trend === 'down'
        ? COLOR_TOKENS.danger.tailwind
        : COLOR_TOKENS.textMuted.tailwind

  const resolvedColor = resolveColorToken(color)

  const isLoading = loading === true
  const showUnit = unit != null && unit.length > 0
  const showChange = !isLoading && change != null && change.length > 0

  return (
    <Card
      className={cn('p-4', border ? 'border-l-4' : '', className)}
      style={border && resolvedColor ? { borderLeftColor: resolvedColor } : undefined}
    >
      <CardContent className="p-0">
        <p className="text-sm text-muted-foreground">{title}</p>
        {isLoading ? (
          <div className="mt-1 h-8 w-24 animate-pulse rounded bg-muted" />
        ) : (
          <div className="mt-1 flex items-baseline gap-1">
            <span
              className="text-2xl font-semibold tracking-tight"
              style={resolvedColor ? { color: resolvedColor } : undefined}
            >
              {value}
            </span>
            {showUnit && <span className="text-sm text-muted-foreground">{unit}</span>}
          </div>
        )}
        {showChange && (
          <p className={cn('mt-2 text-xs', trendColor)}>
            {trend === 'up' ? '↑' : trend === 'down' ? '↓' : '—'} {change}
          </p>
        )}
      </CardContent>
    </Card>
  )
}

/**
 * IntelligentScoreExplanation - 智能评分解释可视化（DA-003）
 *
 * 展示智能评分结果：维度雷达图、关键因子高亮、可折叠的思维链。
 * LLM 原始输出统一经 sanitizeLlmOutput 净化后渲染。
 */

import { memo, useMemo, useState } from 'react'
import { cn } from '@/lib/utils'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/atoms/Card'
import { Badge } from '@/components/atoms/Badge'
import { Button } from '@/components/atoms/Button'
import { DataState } from '@/components/molecules/DataState'
import { ScoreRadar } from '@/components/chart/ScoreRadar'
import { FactorHeatmap, type FactorHeatmapData } from '@/components/chart/FactorHeatmap'
import { ScoreFactorWaterfall } from '@/components/organisms/analysis/score/ScoreFactorWaterfall'
import { sanitizeLlmOutput } from '@/lib/xssSanitizer'
import type { IntelligentScore } from '@/data/types'
import {
  INTELLIGENT_SCORE_EXPLANATION_CONFIG,
  INTELLIGENT_SCORE_EXPLANATION_LABELS,
} from '@/constants/score.constants'
import { CHART_PALETTE } from '@/constants/theme.tokens'

export interface IntelligentScoreExplanationProps {
  result?: IntelligentScore
  loading?: boolean
  error?: string | null
  className?: string
}

const SCORE_SCALE_MAX = 5

/**
 * buildRadarData
 * @param result
/**
 * buildRadarData
 * @param result
 */
// eslint-disable-next-line react-refresh/only-export-components
export function buildRadarData(result: IntelligentScore) {
  return result.dimensionScores
    .filter((dim) => typeof dim.score === 'number' && Number.isFinite(dim.score))
    .slice(0, INTELLIGENT_SCORE_EXPLANATION_CONFIG.maxRadarDimensions)
    .map((dim) => ({
      dimension: dim.name,
      score: dim.score as number,
      fullMark: SCORE_SCALE_MAX,
    }))
}

/**
 * buildKeyFactors
 * @param result
/**
 * buildKeyFactors
 * @param result
 */
// eslint-disable-next-line react-refresh/only-export-components
export function buildKeyFactors(result: IntelligentScore) {
  const valid = result.dimensionScores.filter(
    (dim) => typeof dim.score === 'number' && Number.isFinite(dim.score),
  )
  const sorted = valid.slice().sort((a, b) => (b.score as number) - (a.score as number))
  return sorted.slice(0, INTELLIGENT_SCORE_EXPLANATION_CONFIG.topFactorCount)
}

/**
 * buildFactorHeatmapData
 * @param result
 * @returns FactorHeatmapData[]
/**
 * buildFactorHeatmapData
 * @param result
 * @returns FactorHeatmapData[]
 */
// eslint-disable-next-line react-refresh/only-export-components
export function buildFactorHeatmapData(result: IntelligentScore): FactorHeatmapData[] {
  return result.dimensionScores
    .filter((dim) => typeof dim.score === 'number' && Number.isFinite(dim.score))
    .map((dim) => ({
      name: dim.name,
      value: dim.score as number,
    }))
}

/**
 * IntelligentScoreExplanation
 */
export const IntelligentScoreExplanation = memo(function IntelligentScoreExplanation({
  result,
  loading,
  error,
  className,
}: IntelligentScoreExplanationProps) {
  const [showChain, setShowChain] = useState(!INTELLIGENT_SCORE_EXPLANATION_CONFIG.chainCollapsed)

  const radarData = useMemo(() => (result ? buildRadarData(result) : []), [result])
  const keyFactors = useMemo(() => (result ? buildKeyFactors(result) : []), [result])
  const heatmapData = useMemo(() => (result ? buildFactorHeatmapData(result) : []), [result])
  const sanitizedChain = useMemo(() => {
    if (!result) return ''
    return sanitizeLlmOutput(result.modelResponse ?? result.basis ?? '')
  }, [result])

  const isEmpty = (loading ?? false) !== true && (error ?? '') === '' && !result

  return (
    <Card className={cn('overflow-hidden', className)}>
      <CardHeader className="pb-2">
        <CardTitle className="text-base font-semibold">
          {INTELLIGENT_SCORE_EXPLANATION_LABELS.title}
