      if (originalClose) HTMLDialogElement.prototype.close = originalClose
    }
  })

  // ============ Fake timers 管理 ============
  // 注意：仅「超时分支」测试需要 fake timers；其余异步测试使用 real timers
  // 否则 waitFor 内部 setTimeout 轮询被 fake 后永不触发，导致所有异步测试挂起
  beforeEach(() => {
