import { getLogger } from '@/lib/logger'
import { cn } from '@/lib/utils'

const logger = getLogger()

// ============================================================
// 常量（零硬编码锚点）
// ============================================================

/** 本地运行时长刷新间隔（毫秒） */
const REFRESH_INTERVAL_MS = 1000
/** 顶部统计卡片网格列数 */
const STAT_GRID_COLS = 4
/** Agent 运行时统计网格列数 */
const AGENT_STAT_COLS = 4
/** 权重进度条最大值（百分比制） */
const WEIGHT_PROGRESS_MAX = 100
/** 毫秒与秒换算因子 */
const MS_PER_SECOND = 1000
/** 每分钟秒数 */
const SECONDS_PER_MINUTE = 60
/** 每小时秒数 */
const SECONDS_PER_HOUR = 3600

/** 统计卡片通用样式（边框/背景引用主题令牌，避免硬编码颜色类） */
const STAT_CARD_CLASS = cn(
  'rounded-lg border p-3',
  COLOR_TOKENS.border.tailwind,
  COLOR_TOKENS.bgSlate50.tailwind,
)

/** 网格列模板（基于常量动态生成，避免 Tailwind 动态类名失效） */
const STAT_GRID_STYLE: React.CSSProperties = {
  gridTemplateColumns: `repeat(${STAT_GRID_COLS}, minmax(0, 1fr))`,
}
const AGENT_GRID_STYLE: React.CSSProperties = {
  gridTemplateColumns: `repeat(${AGENT_STAT_COLS}, minmax(0, 1fr))`,
}

// ============================================================
// 纯函数工具
// ============================================================

/**
 * 将 healthSummary.overallStatus（小写）映射为 HEALTH_STATUS 常量（大写）
 * 以便复用 HEALTH_STATUS_MAP 的语义化颜色与标签
 */
function mapOverallStatus(status: string | undefined): HealthStatus {
  switch (status) {
    case 'healthy':
      return HEALTH_STATUS.HEALTHY
    case 'warning':
      return HEALTH_STATUS.WARNING
    case 'critical':
      return HEALTH_STATUS.CRITICAL
    case 'unknown':
      return HEALTH_STATUS.UNKNOWN
    default:
      return HEALTH_STATUS.UNKNOWN
  }
}

/** 将运行时长格式化为 "Xh Ym Zs" */
function formatUptime(started: boolean, startedAt: number, now: number): string {
  if (!started || !startedAt) return '0h 0m 0s'
  const totalSeconds = Math.max(0, Math.floor((now - startedAt) / MS_PER_SECOND))
  const hours = Math.floor(totalSeconds / SECONDS_PER_HOUR)
  const minutes = Math.floor((totalSeconds % SECONDS_PER_HOUR) / SECONDS_PER_MINUTE)
  const seconds = totalSeconds % SECONDS_PER_MINUTE
  return `${hours}h ${minutes}m ${seconds}s`
}

// ============================================================
// 组件
// ============================================================

function EngineStatusCard(): React.JSX.Element {
  const started = useEngineStore((s) => s.started)
  const startedAt = useEngineStore((s) => s.startedAt)
  const stats = useEngineStore((s) => s.stats)
  const layerStatuses = useEngineStore((s) => s.layerStatuses)
  const healthSummary = useEngineStore((s) => s.healthSummary)

  const refreshSnapshot = useSystemMonitorStore((s) => s.refreshSnapshot)
  const systemMonitorIsLoading = useSystemMonitorStore((s) => s.isLoading)

  // 本地时钟：每秒触发一次重绘以刷新运行时长
  const [now, setNow] = useState<number>(() => Date.now())

  // 挂载时拉取一次系统监控快照 + 启动本地运行时长定时器
  useEffect(() => {
    logger.info('[EngineStatusCard] mounted, refreshing system snapshot')
    void refreshSnapshot()

    const timer = setInterval(() => {
      setNow(Date.now())
    }, REFRESH_INTERVAL_MS)

    return () => {
      clearInterval(timer)
      logger.info('[EngineStatusCard] unmounted, timer cleared')
    }
  }, [refreshSnapshot])

  const overallStatus = mapOverallStatus(healthSummary?.overallStatus)
  const statusMeta = HEALTH_STATUS_MAP[overallStatus]
  const uptime = formatUptime(started, getSafeNumber(startedAt), now)

  // 加载态：系统监控正在加载且尚无健康摘要数据时展示占位文本
  const showLoading = systemMonitorIsLoading && !healthSummary

  return (
    <Card>
      <CardHeader className="flex-row items-center justify-between space-y-0">
        <CardTitle className="text-base">引擎状态监控</CardTitle>
        <Badge
          variant="outline"
          className={cn('border-transparent font-semibold text-white', statusMeta.bgClass)}
        >
          {overallStatus}
        </Badge>
      </CardHeader>

      <CardContent className="space-y-4">
        {showLoading ? (
          <p className="text-sm text-muted-foreground">加载中...</p>
        ) : (
          <>
            {/* 顶部统计卡片 */}
            <div className="grid gap-3" style={STAT_GRID_STYLE}>
              {/* 引擎状态 */}
              <div className={STAT_CARD_CLASS}>
                <p className="text-xs text-muted-foreground">引擎状态</p>
                <div className="mt-1 flex items-center gap-1.5">
                  <span
                    className="inline-block h-2 w-2 rounded-full"
                    style={{
                      backgroundColor: started
                        ? COLOR_TOKENS.success.hex
                        : COLOR_TOKENS.danger.hex,
                    }}
                  />
                  <span
                    className="text-sm font-medium"
                    style={{
                      color: started ? COLOR_TOKENS.success.hex : COLOR_TOKENS.danger.hex,
                    }}
                  >
                    {started ? '运行中' : '已停止'}
                  </span>
                </div>
              </div>

              {/* 运行时长 */}
              <div className={STAT_CARD_CLASS}>
                <p className="text-xs text-muted-foreground">运行时长</p>
                <p className="mt-1 text-sm font-medium tabular-nums">{uptime}</p>
              </div>

              {/* 数据流 */}
              <div className={STAT_CARD_CLASS}>
                <p className="text-xs text-muted-foreground">数据流</p>
                <div className="mt-1">
                  <Badge variant={stats.dataflow.connected ? 'success' : 'outline'}>
                    {stats.dataflow.connected ? '已连接' : '未连接'}
                  </Badge>
                </div>
              </div>

              {/* 活跃通道 */}
              <div className={STAT_CARD_CLASS}>
                <p className="text-xs text-muted-foreground">活跃通道</p>
                <p className="mt-1 text-sm font-medium tabular-nums">
                  {stats.dataflow.channels}
                </p>
              </div>
            </div>

            {/* 智能体运行时统计 */}
            <div>
              <p className="mb-2 text-xs font-medium text-muted-foreground">智能体运行时</p>
              <div className="grid gap-3" style={AGENT_GRID_STYLE}>
                <div className={STAT_CARD_CLASS}>
                  <p className="text-xs text-muted-foreground">智能体总数</p>
                  <p className="mt-1 text-sm font-medium tabular-nums">
                    {stats.agents.totalAgents}
                  </p>
                </div>
                <div className={STAT_CARD_CLASS}>
                  <p className="text-xs text-muted-foreground">运行中</p>
                  <p
                    className="mt-1 text-sm font-medium tabular-nums"
                    style={{ color: COLOR_TOKENS.info.hex }}
                  >
                    {stats.agents.runningTasks}
                  </p>
                </div>
                <div className={STAT_CARD_CLASS}>
                  <p className="text-xs text-muted-foreground">已完成</p>
                  <p
                    className="mt-1 text-sm font-medium tabular-nums"
                    style={{ color: COLOR_TOKENS.success.hex }}
                  >
                    {stats.agents.completedTasks}
                  </p>
                </div>
                <div className={STAT_CARD_CLASS}>
                  <p className="text-xs text-muted-foreground">失败</p>
                  <p
                    className="mt-1 text-sm font-medium tabular-nums"
                    style={
                      stats.agents.failedTasks > 0
                        ? { color: COLOR_TOKENS.danger.hex }
                        : undefined
                    }
                  >
                    {stats.agents.failedTasks}
                  </p>
                </div>
              </div>
            </div>

            {/* V6 引擎层 */}
            <div>
              <p className="mb-2 text-xs font-medium text-muted-foreground">
                V6 引擎层（共 {V6_ENGINE_LAYERS.length} 层）
              </p>
              <div className="space-y-2">
                {Object.values(layerStatuses).map((layer) => {
                  const weightPercent = layer.weight * WEIGHT_PROGRESS_MAX
                  const isActive = layer.executionCount > 0
                  return (
                    <div
                      key={layer.layerId}
                      className={cn('rounded-lg border p-3', COLOR_TOKENS.border.tailwind)}
                    >
                      <div className="mb-1.5 flex items-center justify-between gap-2">
                        <div className="min-w-0">
                          <p className="truncate text-sm font-medium">{layer.layerName}</p>
                          <p className="text-xs text-muted-foreground">ID: {layer.layerId}</p>
                        </div>
                        <div className="flex flex-shrink-0 items-center gap-1.5">
                          {layer.deterministic ? (
                            <Badge
                              variant="outline"
                              className={cn(
                                'border-transparent text-white',
                                COLOR_TOKENS.success.bgClass,
                              )}
                            >
                              确定性
                            </Badge>
                          ) : layer.llmEnhanceable ? (
                            <Badge
                              variant="outline"
                              className={cn(
                                'border-transparent text-white',
                                COLOR_TOKENS.purple.bgClass,
                              )}
                            >
                              大模型增强
                            </Badge>
                          ) : null}
                          <Badge variant={isActive ? 'success' : 'secondary'}>
                            {isActive ? '活跃' : '空闲'}
                          </Badge>
                        </div>
                      </div>
                      <Progress
                        value={weightPercent}
                        max={WEIGHT_PROGRESS_MAX}
                        showMax={false}
                        label={`权重 ${weightPercent.toFixed(0)}%`}
                      />
                    </div>
                  )
                })}
              </div>
            </div>
          </>
        )}
      </CardContent>
    </Card>
  )
}

EngineStatusCard.displayName = 'EngineStatusCard'

export default memo(EngineStatusCard)

import React, { useCallback, useState } from 'react'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/atoms/Card'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/molecules/Tabs'
import { getLogger } from '@/lib/logger'
import { useMcpMigration } from './migration/useMcpMigration'
import { MigrationUploadTab } from './migration/MigrationUploadTab'
import { MigrationPreviewTab } from './migration/MigrationPreviewTab'
import { MigrationReportTab } from './migration/MigrationReportTab'
import type { MigrationReport, V6ExportShape, V9ImportShape } from '@/services/system/v6MigrationService'

const logger = getLogger()

export interface BackupSnapshot {
  data: Record<string, unknown[]>
  createdAt: number
  stores: number
  totalRecords: number
}

/**
 * MigrationPanel
 */
export default function MigrationPanel(): React.JSX.Element {
  const [rawJson, setRawJson] = useState<unknown>(null)
  const [v6Export, setV6Export] = useState<V6ExportShape | null>(null)
  const [transformed, setTransformed] = useState<V9ImportShape | null>(null)
  const [report, setReport] = useState<MigrationReport | null>(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const [overwrite, setOverwrite] = useState(false)
  const [activeTab, setActiveTab] = useState('upload')
  const [backup, setBackup] = useState<BackupSnapshot | null>(null)
  const [rollbackStatus, setRollbackStatus] = useState<'idle' | 'rolling' | 'done' | 'failed'>('idle')

  const {
    parseV6Export,
    transformV6ToV9,
    importToV9,
    runV6Migration,
    generateMigrationReport,
    exportAll,
  } = useMcpMigration()

  const handleFile = useCallback(async (file: File) => {
    logger.info('[MigrationPanel] handleFile/start', {
      fileName: file.name,
      fileSize: file.size,
      fileType: file.type,
      timestamp: Date.now(),
    })
    setError('')
    setReport(null)

    const reader = new FileReader()
    reader.onload = async (e) => {
      try {
        const raw = e.target?.result
        const text = typeof raw === 'string' ? raw : ''
        const parsed: unknown = JSON.parse(text)
        setRawJson(parsed)

        const v6 = await parseV6Export(parsed)
        setV6Export(v6)

        const v9 = await transformV6ToV9(v6)
        setTransformed(v9)

        setActiveTab('preview')
        logger.info('[MigrationPanel] 文件解析成功', {
          fileName: file.name,
          v6Stocks: v6.stocks?.length ?? 0,
          v6Orders: v6.orders?.length ?? 0,
          v9Stocks: v9.stocks.length,
          v9Scores: v9.v6Scores.length,
        })
      } catch (err) {
        const message = err instanceof Error ? err.message : String(err)
        setError(`解析失败：${message}`)
        setV6Export(null)
        setTransformed(null)
        logger.error('[MigrationPanel] 文件解析失败', {
          fileName: file.name,
          error: message,
          stack: err instanceof Error ? err.stack : undefined,
          timestamp: Date.now(),
        })
      }
    }
    reader.onerror = () => {
      setError('读取文件失败')
      logger.error('[MigrationPanel] 文件读取失败', {
        fileName: file.name,
        fileSize: file.size,
        error: 'FileReader.onerror triggered',
      })
    }
    reader.readAsText(file)
  }, [parseV6Export, transformV6ToV9])

  async function prepareBackup(): Promise<BackupSnapshot | null> {
    logger.info('[MigrationPanel] overwrite=true,触发二次确认对话框')
    const confirmed = window.confirm(
      '⚠️ 警告:覆盖式导入将删除现有数据!\n\n' +
      '系统将在导入前自动备份当前数据。\n' +
      '如导入失败,可使用「回滚到备份」按钮恢复。\n\n' +
      '确定继续执行覆盖式导入?'
    )
    if (!confirmed) {
      logger.info('[MigrationPanel] 用户取消覆盖式导入')
      return null
    }
    logger.info('[MigrationPanel] 用户确认覆盖式导入,开始备份')
    try {
      logger.info('[MigrationPanel] exportAll/start')
      const backupResult = await exportAll()
      logger.info('[MigrationPanel] exportAll/response', {
        success: backupResult.success,
        hasData: !!backupResult.data,
        error: backupResult.error,
      })
      if (!backupResult.success || !backupResult.data) {
        const backupError = backupResult.error ?? '未知错误'
        setError(`备份失败,已中止导入(防止数据丢失):${backupError}`)
        logger.error('[MigrationPanel] 备份失败,中止导入', {
          error: backupError,
          timestamp: Date.now(),
        })
        return null
      }
      const backupData = backupResult.data
      const stores = Object.keys(backupData)
      const totalRecords = stores.reduce(
        (sum, store) => sum + (backupData[store]?.length ?? 0),
        0,
      )
      const snapshot: BackupSnapshot = {
        data: backupData,
        createdAt: Date.now(),
        stores: stores.length,
        totalRecords,
      }
      setBackup(snapshot)
      logger.info('[MigrationPanel] 备份完成', {
        stores: stores.length,
        totalRecords,
        storeNames: stores,
      })
      return snapshot
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      setError(`备份异常,已中止导入:${message}`)
      logger.error('[MigrationPanel] 备份异常', {
        error: message,
        stack: err instanceof Error ? err.stack : undefined,
      })
      return null
    }
  }

  const handleImport = useCallback(async () => {
    if (!transformed) return
    logger.info('[MigrationPanel] handleImport/start', {
      overwrite,
      hasTransformed: transformed !== null,
      stocksCount: transformed.stocks.length,
      timestamp: Date.now(),
    })

    let backupSnapshot: BackupSnapshot | null = null
    if (overwrite) {
      backupSnapshot = await prepareBackup()
      if (backupSnapshot === null) return
    } else {
      logger.info('[MigrationPanel] overwrite=false,跳过备份直接导入')
    }

    setLoading(true)
    setError('')
    logger.info('[MigrationPanel] importToV9/start', {
      overwrite,
      stocksCount: transformed.stocks.length,
      hasBackup: backupSnapshot !== null,
    })
    try {
      const result = await importToV9(transformed, { overwriteExisting: overwrite })
      setReport(result)
      setActiveTab('report')
      logger.info('[MigrationPanel] 导入完成', {
        overwrite,
        importedRecords: result.summary.importedRecords,
        skippedRecords: result.summary.skippedRecords,
        failedRecords: result.summary.failedRecords,
        totalStores: result.summary.totalStores,
        backupCreated: backupSnapshot !== null,
        timestamp: Date.now(),
      })
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      setError(`导入失败:${message}`)
      logger.error('[MigrationPanel] 导入失败', {
        error: message,
        stack: err instanceof Error ? err.stack : undefined,
        hasBackup: backupSnapshot !== null,
        overwrite,
        timestamp: Date.now(),
      })
    } finally {
      setLoading(false)
    }
  }, [transformed, overwrite, prepareBackup, importToV9])

  const withBackup = useCallback(
    (fn: (currentBackup: BackupSnapshot) => void): void => {
      if (!backup) return
      fn(backup)
    },
    [backup],
  )

  const handleDownloadBackup = useCallback(() => {
    withBackup((currentBackup) => {
      logger.info('[MigrationPanel] handleDownloadBackup/start', {
        stores: currentBackup.stores,
        totalRecords: currentBackup.totalRecords,
        createdAt: currentBackup.createdAt,
      })
      const json = JSON.stringify(currentBackup.data, null, 2)
      const blob = new Blob([json], { type: 'application/json' })
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = `v9-backup-${new Date(currentBackup.createdAt).toISOString().replace(/[:.]/g, '-')}.json`
      document.body.appendChild(a)
      a.click()
      document.body.removeChild(a)
      URL.revokeObjectURL(url)
      logger.info('[MigrationPanel] 备份已下载', {
        stores: currentBackup.stores,
        totalRecords: currentBackup.totalRecords,
        filename: a.download,
        blobSize: blob.size,
      })
    })
  }, [withBackup])

  const handleRollback = useCallback(() => {
    withBackup((currentBackup) => {
      logger.warn('[MigrationPanel] handleRollback/start', {
        backupCreatedAt: currentBackup.createdAt,
        backupStores: currentBackup.stores,
        backupTotalRecords: currentBackup.totalRecords,
        timestamp: Date.now(),
      })
      setRollbackStatus('rolling')
    logger.info('[MigrationPanel] 触发备份下载以供手动恢复')
    handleDownloadBackup()
    setRollbackStatus('done')
    logger.info('[MigrationPanel] handleRollback/complete', {
      rollbackStatus: 'done',
      message: '已下载备份文件,等待用户手动恢复',
    })
    setError(
      `已下载备份文件(共 ${currentBackup.stores} 个 store,${currentBackup.totalRecords} 条记录)。\n` +
      '请使用「上传」功能导入此备份文件以恢复数据。\n' +
      '注意:恢复前请先在总控舱点击「重置数据」清空当前状态。'
    )
  })
}, [withBackup, handleDownloadBackup])

  const handleRunMigration = useCallback(async () => {
    if (!rawJson) return
    logger.info('[MigrationPanel] handleRunMigration/start', {
      hasRawJson: rawJson !== null,
      overwrite,
      timestamp: Date.now(),
    })
    setLoading(true)
    setError('')
    try {
      const result = await runV6Migration(rawJson, { overwriteExisting: overwrite })
      logger.info('[MigrationPanel] runV6Migration/response', {
        success: result.success,
        hasData: !!result.data,
        error: result.error,
      })
      if (result.success && result.data) {
        setReport(result.data)
        setActiveTab('report')
        logger.info('[MigrationPanel] 快速迁移完成', {
          overwrite,
          importedRecords: result.data.summary.importedRecords,
          skippedRecords: result.data.summary.skippedRecords,
          failedRecords: result.data.summary.failedRecords,
          totalStores: result.data.summary.totalStores,
          timestamp: Date.now(),
        })
      } else {
        const migrationError = result.error ?? '迁移失败'
        setError(migrationError)
        logger.warn('[MigrationPanel] 快速迁移失败响应', {
          error: migrationError,
          overwrite,
        })
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err)
      setError(`迁移失败：${message}`)
      logger.error('[MigrationPanel] 快速迁移异常', {
        error: message,
        stack: err instanceof Error ? err.stack : undefined,
        overwrite,
        timestamp: Date.now(),
      })
    } finally {
      setLoading(false)
    }
  }, [rawJson, overwrite, runV6Migration])

  const handleReset = useCallback(() => {
    setRawJson(null)
    setV6Export(null)
    setTransformed(null)
    setReport(null)
    setBackup(null)
    setRollbackStatus('idle')
    setError('')
    setActiveTab('upload')
  }, [])

  return (
    <Card className="w-full">
      <CardHeader>
        <CardTitle>V6 Pro → V9 数据迁移</CardTitle>
        <CardDescription>
          上传 V6 Pro 的 JSON 全量导出文件，预览并导入到 V9。
        </CardDescription>
      </CardHeader>
      <CardContent>
        <Tabs value={activeTab} onValueChange={setActiveTab}>
          <TabsList>
            <TabsTrigger value="upload">上传</TabsTrigger>
            <TabsTrigger value="preview" disabled={!transformed}>预览</TabsTrigger>
            <TabsTrigger value="report" disabled={!report}>报告</TabsTrigger>
          </TabsList>

          <TabsContent value="upload">
            <MigrationUploadTab error={error} onFileSelected={(file) => void handleFile(file)} />
          </TabsContent>

          <TabsContent value="preview">
            <MigrationPreviewTab
              v6Export={v6Export}
              transformed={transformed}
              overwrite={overwrite}
              onOverwriteChange={setOverwrite}
              onImport={() => void handleImport()}
              onRunMigration={() => void handleRunMigration()}
              loading={loading}
              error={error}
              backup={backup}
              onDownloadBackup={handleDownloadBackup}
              onRollback={handleRollback}
              rollbackStatus={rollbackStatus}
            />
          </TabsContent>

          <TabsContent value="report">
            <MigrationReportTab
              report={report}
              onGenerateReport={generateMigrationReport}
              onReset={handleReset}
            />
          </TabsContent>
        </Tabs>
      </CardContent>
    </Card>
  )
}

/**
 * SystemArchitectureDiagram 组件单元测试
 *
 * 覆盖场景（对应独立复检报告 cockpit-架构图独立复检报告.md 的验收项）：
 * 1. 数据加载失败/无数据时显示「暂无架构数据」兜底
 * 2. 渲染全部 8 个分层卡片与分层数徽标
 * 3. 渲染层间连接箭头（↓）与连接标签
 * 4. 渲染 V6 评分引擎层与权重百分比
