  market: 'SH' | 'SZ' | 'BJ'
  industry: string
  addedAt: string
  lastCollectTime: string | null
  dimensions: Record<DataDimensionType, DimensionStatus>
}

/** 全局 meta.json 结构 */
export interface GlobalMeta {
  version: string
  schemaVersion: string
  createdAt: string
  lastUpdated: string
