      const registry = new HandlerRegistry()
      const mockHandler: EnvelopeHandler = {
        canHandle: vi.fn(() => false),
        handle: vi.fn(),
      }

      registry.register(mockHandler)

      // 通过 findHandler 验证注册成功
      expect(registry.findHandler('nonexistent')).toBeUndefined()
    })

    it('findHandler 找到匹配的 handler', () => {
      const registry = new HandlerRegistry()
      const mockHandler: EnvelopeHandler = {
        canHandle: vi.fn((action) => action === 'TEST_ACTION'),
        handle: vi.fn(),
      }
      registry.register(mockHandler)

      const found = registry.findHandler('TEST_ACTION')
      expect(found).toBe(mockHandler)
    })

    it('findHandler 找不到时返回 undefined', () => {
      const registry = new HandlerRegistry()
      const mockHandler: EnvelopeHandler = {
        canHandle: vi.fn(() => false),
        handle: vi.fn(),
      }
      registry.register(mockHandler)

      expect(registry.findHandler('UNKNOWN_ACTION')).toBeUndefined()
    })

    it('多个 handler 时按注册顺序匹配（第一个匹配优先）', () => {
      const registry = new HandlerRegistry()
      const handler1: EnvelopeHandler = {
        canHandle: vi.fn((action) => action === 'SHARED_ACTION'),
        handle: vi.fn(),
      }
      const handler2: EnvelopeHandler = {
        canHandle: vi.fn((action) => action === 'SHARED_ACTION'),
        handle: vi.fn(),
      }
      registry.register(handler1)
      registry.register(handler2)

      const found = registry.findHandler('SHARED_ACTION')
      expect(found).toBe(handler1)
      expect(handler2.canHandle).not.toHaveBeenCalled()
    })
  })

  // ──────────────────────────────────────────
  // createHandlerRegistry
  // ──────────────────────────────────────────
  describe('createHandlerRegistry', () => {
    it('正确创建所有 handler', () => {
      const registry = createHandlerRegistry()
      expect(registry).toBeInstanceOf(HandlerRegistry)
    })

    it('InsertStock 能找到对应 handler', () => {
      const registry = createHandlerRegistry()
      const handler = registry.findHandler(ENVELOPE_ACTION.insertStock)
      expect(handler).toBeDefined()
      expect(handler!.canHandle(ENVELOPE_ACTION.insertStock)).toBe(true)
    })

    it('UpdateStock 能找到对应 handler', () => {
      const registry = createHandlerRegistry()
      const handler = registry.findHandler(ENVELOPE_ACTION.updateStock)
      expect(handler).toBeDefined()
    })

    it('DeleteStock 能找到对应 handler', () => {
      const registry = createHandlerRegistry()
      const handler = registry.findHandler(ENVELOPE_ACTION.deleteStock)
      expect(handler).toBeDefined()
    })

    it('UpdateStockStatus 能找到对应 handler', () => {
      const registry = createHandlerRegistry()
      const handler = registry.findHandler(ENVELOPE_ACTION.updateStockStatus)
      expect(handler).toBeDefined()
    })

    it('UpdateStockGroup 能找到对应 handler', () => {
      const registry = createHandlerRegistry()
      const handler = registry.findHandler(ENVELOPE_ACTION.updateStockGroup)
      expect(handler).toBeDefined()
    })

    it('Bulk 类 action 能找到对应 handler', () => {
      const registry = createHandlerRegistry()
      expect(registry.findHandler(ENVELOPE_ACTION.bulkInsertStock)).toBeDefined()
      expect(registry.findHandler(ENVELOPE_ACTION.bulkSaveDailyQuotes)).toBeDefined()
      expect(registry.findHandler(ENVELOPE_ACTION.bulkSaveScores)).toBeDefined()
    })

    it('Delete 类 action 能找到对应 handler', () => {
      const registry = createHandlerRegistry()
      expect(registry.findHandler(ENVELOPE_ACTION.deleteExecutionPlan)).toBeDefined()
      expect(registry.findHandler(ENVELOPE_ACTION.deleteCustomAgent)).toBeDefined()
    })

    it('SaveCustomAgent 能找到对应 handler', () => {
      const registry = createHandlerRegistry()
      const handler = registry.findHandler(ENVELOPE_ACTION.saveCustomAgent)
      expect(handler).toBeDefined()
    })

    it('Put 类 action 能找到对应 handler', () => {
      const registry = createHandlerRegistry()
      expect(registry.findHandler(ENVELOPE_ACTION.saveScores)).toBeDefined()
      expect(registry.findHandler(ENVELOPE_ACTION.saveFinancialReport)).toBeDefined()
      expect(registry.findHandler(ENVELOPE_ACTION.saveDailyQuotes)).toBeDefined()
    })

    it('优先级顺序：特殊处理器优先于通用 PutHandler', () => {
      const registry = createHandlerRegistry()
      // insertStock 应该被 InsertStockHandler 处理，而不是 PutHandler
      const handler = registry.findHandler(ENVELOPE_ACTION.insertStock)
      expect(handler).toBeDefined()
      // InsertStockHandler 只处理 insertStock
      expect(handler!.canHandle(ENVELOPE_ACTION.saveScores)).toBe(false)
    })

    it('未知 action 找不到 handler', () => {
      const registry = createHandlerRegistry()
      expect(registry.findHandler('UNKNOWN_RANDOM_ACTION')).toBeUndefined()
    })
  })
})

import { describe, it, expect, vi, beforeEach } from 'vitest'
import {
  routeToStrategy,
  setStrategyAnalyzers,
  STRATEGY_CHANNEL,
} from './databridgeStrategyRouter'
import { EnvelopeFactory, EnvelopeError } from './envelope'
import { ENVELOPE_ACTION, MODULE_ID } from '@/config/dbConfig'
import { EVENT_NAMES } from '@/constants/store-channels.constants'
import { eventBus } from '@/lib/eventBus'

// Mock eventBus
vi.mock('@/lib/eventBus', () => ({
  eventBus: {
    emit: vi.fn(),
  },
}))

const mockHotSectorScore = (symbol: string, score: number, action: string) => ({
  symbol,
  score,
  action,
  dimensions: {
    momentum: 80,
    sentiment: 70,
    technical: 75,
    valuation: 65,
    marketEnv: 60,
  },
  updatedAt: Date.now(),
})

const mockValuePitScore = (symbol: string, score: number, action: string) => ({
  symbol,
  score,
  action,
  dimensions: {
    catalyst: 70,
    valuation: 80,
    chip: 65,
    rotation: 75,
    liquidity: 85,
  },
  updatedAt: Date.now(),
})

const mockRotationSignal = (sectorId: string, triggered: boolean, strength: string) => ({
  sectorId,
  triggered,
  strength,
  conditions: {
    volumeBreakthrough: triggered,
    capitalInflow: triggered,
    goldenCross: triggered,
  },
  detectedAt: Date.now(),
})

describe('databridgeStrategyRouter', () => {
  const mockAnalyzers = {
    analyzeHotSector: vi.fn(),
    analyzeValuePit: vi.fn(),
    detectRotation: vi.fn(),
  }

  const mockContext = {
    subscribers: new Map<string, Set<(e: any) => void>>(),
    broadcast: vi.fn(),
  }

  beforeEach(() => {
    vi.clearAllMocks()
    mockContext.subscribers.clear()
    setStrategyAnalyzers(mockAnalyzers as any)
  })

  describe('STRATEGY_CHANNEL 常量', () => {
    it('定义了三个策略频道', () => {
      expect(STRATEGY_CHANNEL.hotSector).toBe('strategy:hotSector')
      expect(STRATEGY_CHANNEL.valuePit).toBe('strategy:valuePit')
      expect(STRATEGY_CHANNEL.rotationSignal).toBe('strategy:rotationSignal')
    })
  })

  describe('setStrategyAnalyzers()', () => {
    it('注入分析器后不报错', () => {
      expect(() => setStrategyAnalyzers(mockAnalyzers as any)).not.toThrow()
    })
  })

  describe('routeToStrategy() - HotSector', () => {
    it('正常流程：逐板块评分并广播', () => {
      mockAnalyzers.analyzeHotSector
        .mockReturnValueOnce(mockHotSectorScore('sector1', 85, 'immediate'))
        .mockReturnValueOnce(mockHotSectorScore('sector2', 70, 'probe'))

      const envelope = EnvelopeFactory.create(
        {
          action: ENVELOPE_ACTION.strategyHotSectorRefresh,
          source: MODULE_ID.strategy,
          target: 'db',
          traceId: 'test-hs-001',
        },
        [
          { symbol: 'sector1' },
          { symbol: 'sector2' },
        ],
      )

      routeToStrategy(envelope, mockContext)

      expect(mockAnalyzers.analyzeHotSector).toHaveBeenCalledTimes(2)
      expect(mockContext.broadcast).toHaveBeenCalledTimes(1)
      expect(mockContext.broadcast).toHaveBeenCalledWith(
        STRATEGY_CHANNEL.hotSector,
        expect.objectContaining({
          meta: expect.objectContaining({
            target: STRATEGY_CHANNEL.hotSector,
          }),
          payload: expect.arrayContaining([
            expect.objectContaining({ symbol: 'sector1' }),
            expect.objectContaining({ symbol: 'sector2' }),
          ]),
        }),
      )
    })

    it('EventBus 触发 HOT_SECTOR_CHANGED', () => {
      mockAnalyzers.analyzeHotSector
        .mockReturnValue(mockHotSectorScore('sector1', 80, 'probe'))

      const envelope = EnvelopeFactory.create(
        {
          action: ENVELOPE_ACTION.strategyHotSectorRefresh,
          source: MODULE_ID.strategy,
          target: 'db',
          traceId: 'test-hs-002',
        },
        [{ symbol: 'sector1' }],
      )

      routeToStrategy(envelope, mockContext)

      expect(eventBus.emit).toHaveBeenCalledWith(
        EVENT_NAMES.HOT_SECTOR_CHANGED,
        expect.any(Array),
      )
    })

    it('payload 不是数组时抛出 EnvelopeError', () => {
      const envelope = EnvelopeFactory.create(
        {
          action: ENVELOPE_ACTION.strategyHotSectorRefresh,
          source: MODULE_ID.strategy,
          target: 'db',
          traceId: 'test-hs-003',
        },
        'not-an-array',
      )

      expect(() => routeToStrategy(envelope, mockContext)).toThrow(EnvelopeError)
      expect(() => routeToStrategy(envelope, mockContext)).toThrow('payload 必须是数组')
    })

    it('订阅者数量被正确统计', () => {
      mockAnalyzers.analyzeHotSector
        .mockReturnValue(mockHotSectorScore('s1', 80, 'probe'))

      const subscribers = new Set([() => {}, () => {}])
      const context = {
        subscribers: new Map([[STRATEGY_CHANNEL.hotSector, subscribers]]),
        broadcast: vi.fn(),
      }

      const envelope = EnvelopeFactory.create(
        {
          action: ENVELOPE_ACTION.strategyHotSectorRefresh,
          source: MODULE_ID.strategy,
          target: 'db',
          traceId: 'test-hs-004',
        },
        [{ symbol: 's1' }],
      )

      expect(() => routeToStrategy(envelope, context)).not.toThrow()
      expect(context.broadcast).toHaveBeenCalledTimes(1)
    })
  })

  describe('routeToStrategy() - ValuePit', () => {
