    })

    it('混合场景：一只股票显式 0 + 一只缺失', () => {
      const stocks = createPoolStocks([
        { symbol: '688981.SH', name: '中芯国际', v6Composite: 0 },
        { symbol: '688012.SH', name: '中微公司' },
      ])

