        expect.stringContaining('显式 0')
      )
      expect(mockDebug).not.toHaveBeenCalledWith(
        expect.stringContaining('缺失')
      )
    })

    it('输出 v6Composite 为 NaN → 输入必为 null/undefined', () => {
