      )
      const missingCalls = mockDebug.mock.calls.filter((c: any[]) =>
        c[0]?.includes('缺失')
      )
      expect(zeroCalls.length).toBe(1)
      expect(missingCalls.length).toBe(1)
    })
  })
})

