import { describe, test, expect, vi } from 'vitest'
import { detectMainForceChipFlow, computeTurnoverVolumeEnergy, classifyBreakoutStyle } from './l7_l8'
import type { LayerInput, FundFlowContext } from '../types'

vi.mock('@/lib/logger', () => ({
