    scenario: '0.2%换手 + 2.0量比 → 能量0.004=L1 → breakout_watch',
    input: { turnover: 0.002, turnoverPct: 0.2, volumeRatio: 2, latestReturn1d: 0.001, return60d: -0.08, turnover20dStd: 0.0008 },
