    input: { turnover: 0.06, turnoverPct: 6, volumeRatio: 2.5, latestReturn1d: 0.04, return60d: 0.12, turnover20dStd: 0.018 },
    expected: { style: 'sniper_breakout', energyLevel: 5 },
