  unsubscribes,
} = vi.hoisted(() => {
  const capturedCallbacks = new Map<string, ((envelope: StandardEnvelope) => void)>()
  const unsubscribes: Array<ReturnType<typeof vi.fn>> = []
  return {
    mockDataBridgeQuery: vi.fn().mockResolvedValue({ success: true, data: [] }),
