// ============================================================
// Imports
// ============================================================

import { useExecutionStore } from './executionStore'

// ============================================================
// Setup
// ============================================================

const initialState = {
  plans: [] as ExecutionPlan[],
  activePlans: [] as ExecutionPlan[],
  isProcessing: false,
