  return {
    id: 'plan-001',
    symbol: 'AAPL',
    name: 'AAPL 买入计划',
    phase: 'plan',
    direction: 'buy',
    quantity: 100,
    targetPrice: 150,
    currentPrice: 145,
    rationale: '突破信号',
