        catalyst: { policyCatalyst: 5, cycleTurningPoint: 5, techBreakthrough: 5, orderSurge: 5 },
        valuationMargin: { pePercentile: 5, pbPercentile: 5, dividendYield: 5, peg: 0.4 },
